// V3D CAD – Hilfe-Inhalte (Seite „📖 Hilfe“ in volme3d.html, PDF über tools/bau_hilfe_pdf.mjs)
// Je Eintrag: b = Bereich, i = Symbol, t = Titel, k = Suchwörter, was = was es macht,
// wo = wo man es findet (B: V3D-CAD, A: V3D-SionCAD), s = Schritte, tipp = Hinweis,
// run = JS-Ausdruck für „Jetzt öffnen“ (optional), video = Howto-Video-ID (optional).
// Neue Funktion? Hier einen Eintrag ergänzen — die Seite und das PDF lesen nur diese Datei.
window.V3D_HILFE_BEREICHE = [
  'Erste Schritte', 'Formen & Teile', 'Skizze & Extrudieren', 'Kombinieren', 'Anordnen',
  'Form ändern', 'Gewinde & Bewegung', 'Oberfläche & Aussehen', 'Generatoren', 'Prüfen',
  'Drucken & Export', 'Datei & Hilfe', 'Generatoren A–Z'
];
window.V3D_HILFE = [
  // ── Erste Schritte ─────────────────────────────────────────────────────
  { b: 'Erste Schritte', i: '🕘', t: 'Versionen (ältere Stände)', k: 'versionen verlauf backup sicherung wiederherstellen festhalten kopie historie alter stand',
    was: 'V3D CAD hebt ältere Stände deines Designs automatisch auf (bis 30 Tage) und du kannst wichtige Stände mit Namen festhalten.',
    wo: 'Menü (☰) → „🕘 Versionen“, oder Suche „Versionen“.',
    s: ['<b>📌 Aktuellen Stand festhalten…</b>: Namen eingeben. Diese Version bleibt immer.', '<b>↩</b> stellt einen Stand wieder her (der aktuelle wird vorher gesichert).', '<b>⧉</b> öffnet einen Stand als eigenes Design, das Original bleibt unverändert.', 'Automatisch: die letzte Stunde alle 5 Minuten, dann stündlich (1 Tag) und täglich (30 Tage).'], run: '_bakOpen()' },
  { b: 'Erste Schritte', i: '🎓', t: 'Interaktive Anleitungen', k: 'anleitung tutorial lernen schritt für schritt übung becher halter einstieg kurs',
    was: 'Baue ein Modell Schritt für Schritt direkt im Programm nach. Jeder Schritt wird geprüft, dann geht es von allein weiter.',
    wo: 'Hier: „▶ Jetzt öffnen“, oder Suche „Anleitung“.',
    s: ['Anleitung wählen (Stiftebecher, Halter mit Lochreihe, Schlüsselanhänger, Flansch mit Lochkreis oder Altes STL bearbeitbar machen) und <b>Starten</b>.', 'Oben rechts steht, was zu tun ist. Ist der Schritt geschafft, wird der Rahmen kurz grün und der nächste erscheint.', 'Dein eigenes Projekt ist solange beiseitegelegt und kommt mit <b>Beenden</b> unverändert zurück.'], run: '_tutMenu()' },
  { b: 'Erste Schritte', i: '🖱️', t: 'Ansicht drehen, verschieben, zoomen', k: 'maus navigation orbit pan zoom touchpad drehen verschieben einpassen',
    was: 'So bewegst du dich um dein Modell herum. Das Modell selbst bleibt dabei, wo es ist.',
    wo: 'Überall in der 3D-Ansicht.',
    s: ['<b>Rechte Maustaste gedrückt halten und ziehen</b> = Ansicht drehen.', '<b>Mittlere Maustaste</b> (oder Shift + rechte Taste) ziehen = verschieben.', '<b>Mausrad</b> = zoomen. Touchpad: zwei Finger wischen = verschieben, auf/zu = zoomen.', '<b>F</b> = alles einpassen, <b>Doppelklick</b> auf ein Teil = darauf zoomen.'] },
  { b: 'Erste Schritte', i: '🧊', t: 'Ansichtswürfel & feste Ansichten', k: 'viewcube würfel oben vorne rechts iso pfeile 90 grad orthogonal perspektive',
    was: 'Der Würfel oben rechts zeigt, von wo du schaust, und bringt dich schnell in eine Standardansicht.',
    wo: 'Oben rechts in der 3D-Ansicht; unten links die Knöpfe OBEN · VORNE · RECHTS · ISO.',
    s: ['Auf eine <b>Würfelfläche klicken</b> (z. B. RECHTS) → Ansicht genau von dort.', 'Die <b>Pfeile ◀ ▶ ▲ ▼</b> am Würfel schwenken um 90°.', 'Am Würfel <b>ziehen</b> dreht frei.'],
    tipp: 'Für genaue Seitenansichten ohne Verzerrung links in der Leiste auf „Orthogonale Ansicht“ umschalten.' },
  { b: 'Erste Schritte', i: '⛶', t: 'Vollbild', k: 'vollbild fullscreen beamer präsentation f11',
    was: 'Blendet Adressleiste und Tabs des Browsers aus — mehr Platz, ideal am Beamer.',
    wo: 'Oben rechts in der schwarzen Leiste, links neben „Videos“ (Symbol ⛶). Oder F11.',
    s: ['Auf <b>⛶</b> klicken.', 'Zurück mit <b>Esc</b> oder nochmal klicken.'], run: '_fsToggle()' },
  { b: 'Erste Schritte', i: '🧒', t: 'V3D Kids (Kinder-Einstieg)', k: 'kinder kids kinderkurs schule vhs einfach kacheln spielstadt eisenbahn',
    was: 'Ein Einstieg für Kinder: Statt des Startdialogs erscheint eine Seite mit großen Kacheln (Spielstadt, Eisenbahn, Fahrzeuge, Figuren, Geschenke). Nach dem Bauen hilft eine Leiste unten weiter. Die ganze Werkstatt bleibt dahinter erreichbar.',
    wo: 'Adresse <b>…/kids</b> aufrufen (oder <b>volme3d.html?kids=1</b>) – am besten als Lesezeichen auf den Kurs-Rechnern.',
    s: ['Eine Kachel antippen, z. B. <b>🚂 Zug</b>.', 'Im Generator einstellen und <b>✓ Erstellen</b> klicken.', 'Unten <b>➕ Noch etwas bauen</b>, <b>↩️ Rückgängig</b> oder <b>🖨️ Für den Drucker speichern</b> (3MF-Datei) wählen.', '<b>🔧 Große Werkstatt</b> verlässt den Kinder-Einstieg.'],
    tipp: 'Alle Spielwelt-Teile (Straßen, Landschaft, Schienen, Brücken) passen zusammen: Straßen- und Landschaftsplatten haben 144 mm und Puzzle-Kanten, die Schienen das Holzeisenbahn-Maß.', run: '_kidsStart() || _kidsPageOpen()' },
  { b: 'Erste Schritte', i: '👆', t: 'Teile auswählen', k: 'auswahl auswählen markieren mehrere shift rahmen lasso alles',
    was: 'Ein ausgewähltes Teil bekommt Griffe und kann bearbeitet werden.',
    wo: 'Links in der Leiste ganz oben: Auswahl (Q).',
    s: ['<b>Klick</b> auf ein Teil wählt es aus.', '<b>Shift + Klick</b> fügt weitere hinzu.', 'Im Leeren <b>ziehen</b> = Auswahlrahmen. <b>Strg+A</b> = alles.', 'Für unregelmäßige Bereiche: Freiform-Auswahl (Lasso).'] },
  { b: 'Erste Schritte', i: '✥', t: 'Verschieben, drehen, skalieren', k: 'bewegen verschieben drehen rotieren skalieren größe griffe pfeile gizmo w e r boden d',
    was: 'Mit den Griffen am ausgewählten Teil veränderst du Lage und Größe direkt mit der Maus.',
    wo: 'Am ausgewählten Teil. Tasten: W bewegen, E drehen, R skalieren, D auf den Boden.',
    s: ['An einem <b>Pfeil</b> ziehen verschiebt in diese Richtung.', 'An einem <b>Ring</b> ziehen dreht (Shift = 45°-Schritte).', '<b>Weiße Ecken</b> skalieren alles, <b>schwarze Punkte</b> nur eine Richtung.', '<b>Pfeiltasten</b> schieben genau (Shift = fein, Strg ↑↓ = hoch/runter).'] },
  { b: 'Erste Schritte', i: '📏', t: 'Maße genau eintippen', k: 'maße millimeter eintippen breite tiefe höhe tab eigenschaften maß fenster',
    was: 'Größe und Position millimetergenau eingeben statt ziehen.',
    wo: 'Rechts im Reiter EIGENSCHAFTEN — oder Klick auf eine weiße Ecke am Teil.',
    s: ['Teil auswählen, rechts <b>EIGENSCHAFTEN</b> öffnen.', 'Breite, Tiefe, Höhe eintippen — <b>Tab</b> springt zum nächsten Feld.', 'Im Maß-Fenster an der weißen Ecke übernimmt <b>Enter</b> alle drei Werte.'] },
  { b: 'Erste Schritte', i: '✂️', t: 'Rückgängig, Kopieren, Einfügen, Löschen', k: 'rückgängig undo wiederholen redo kopieren einfügen duplizieren löschen ausschneiden rechtsklick',
    was: 'Die Klassiker — auch per Rechtsklick auf ein Teil.',
    wo: 'Oben: ↩ Rückgängig / ↪ Wiederholen / 🗑. Rechtsklick auf ein Teil öffnet das Menü.',
    s: ['<b>Strg+Z</b> rückgängig, <b>Strg+Y</b> wiederholen.', '<b>Strg+C / Strg+V</b> kopieren/einfügen, <b>Strg+X</b> ausschneiden, <b>Strg+D</b> duplizieren.', '<b>Entf</b> löscht. <b>Alt + ziehen</b> zieht eine Kopie heraus.'] },
  { b: 'Erste Schritte', i: '⇄', t: 'V3D-CAD | V3D-SionCAD | V3D-ShapeCAD', k: 'v3d-cad sioncad shapecad beginner advanced umsteiger modus arbeitsweise fusion onshape shapr3d tinkercad browser umschalten',
    was: 'Drei Anordnungen derselben Werkzeuge – ein Modell. V3D-CAD (Standard): Formen zusammenschieben wie in Tinkercad. V3D-SionCAD für Umsteiger von Fusion: Skizze → Extrudieren → Verlauf, Browser links, Tastenkürzel wie dort. V3D-ShapeCAD für Umsteiger von Shapr3D: Werkzeugspalte links, Werkzeuge direkt an der Auswahl, Flächen am Pfeil ziehen – gut für Tablet und Stift. Beim Umschalten bleibt das Modell gleich.',
    wo: 'Oben in der schwarzen Leiste neben der Versionsnummer.',
    s: ['Auf <b>V3D-CAD</b>, <b>V3D-SIONCAD</b> oder <b>V3D-SHAPECAD</b> klicken.', 'In V3D-SionCAD stehen vorne <b>Erstellen</b> und <b>Konstruieren</b>, links der <b>Browser</b> mit Körpern und Skizzen.', 'Zurück zu <b>V3D-CAD</b> geht jederzeit – was du gebaut hast, lässt sich dort weiterbearbeiten.'],
    run: "_advSet(_advMode === 'advanced' ? 'beginner' : 'advanced')" },
  { b: 'Erste Schritte', i: '▦', t: 'Symbole statt Text', k: 'symbole piktogramme icons symbolleiste aufgeräumt kompakt text leiste gruppen',
    was: 'Zeigt die Werkzeuge oben als schlichte Symbole in farbig umrandeten Gruppen statt mit Text — viel aufgeräumter, meist passt alles in eine Zeile. Geht in V3D-CAD und V3D-SionCAD.',
    wo: 'Oben in der schwarzen Leiste rechts neben V3D-CAD | V3D-SionCAD: <b>SYMBOLE</b>.',
    s: ['Auf <b>SYMBOLE</b> klicken.', 'Maus über ein Symbol halten — Name und Erklärung erscheinen. Am Handy/Tablet: <b>lange drücken</b> erklärt, ohne auszuführen.', 'Nochmal <b>SYMBOLE</b> = wieder mit Text. Die Wahl wird gemerkt.'],
    run: '_symToggle()' },
  { b: 'Erste Schritte', i: '🔍', t: 'Befehl suchen', k: 'suche befehl finden strg k palette',
    was: 'Jede Funktion in Sekunden finden und starten, ohne zu wissen, wo sie steckt.',
    wo: 'Oben „🔍 Suche“ oder Strg+K.',
    s: ['<b>Strg+K</b> drücken.', 'Ein Wort tippen, z. B. „spiegeln“ oder „gewinde“.', 'Mit Enter starten.'], run: '_cmdkOpen()' },
  { b: 'Erste Schritte', i: '▱', t: 'Arbeitsebene', k: 'arbeitsebene workplane fläche ebene schräg versetzen kippen',
    was: 'Legt eine neue „Bauplatte“ auf eine beliebige Fläche. Neue Formen und Skizzen landen dann genau dort — auch schräg.',
    wo: 'V3D-CAD: links in der Leiste (P). V3D-SionCAD: Konstruieren → Arbeitsebene.',
    s: ['Arbeitsebene anklicken.', 'Eine Fläche eines Teils anklicken.', 'Im Fenster lässt sie sich versetzen oder kippen. Klick ins Leere setzt sie zurück.'], run: 'toggleWorkplane()' },

  // ── Formen & Teile ─────────────────────────────────────────────────────
  { b: 'Formen & Teile', i: '⬛', t: 'Grundformen hinzufügen', k: 'form grundform box zylinder kugel kegel torus pyramide rohr keil stern herz dach halbkugel edelstein kapsel pfeil',
    was: 'Box, Zylinder, Kugel, Kegel, Torus, Pyramide, Rohr, Keil, Stern, Herz, Satteldach, Runddach, Halbkugel, Edelstein, Kapsel, Pfeil u. v. m.',
    wo: 'Rechts im Reiter SHAPES → „Körper hinzufügen“. Tasten 1–5 für die häufigsten.',
    s: ['„Körper hinzufügen“ öffnen.', 'Form anklicken — sie erscheint auf der Bauplatte (oder auf der Arbeitsebene).', 'Mit Griffen oder Maßen anpassen.'], run: "addShape('box')" },
  { b: 'Formen & Teile', i: '⭕', t: 'Solid oder Bohrung', k: 'bohrung loch solid hole markieren abziehen h s',
    was: 'Jede Form kann ein fester Körper (Solid) oder eine Bohrung sein. Bohrungen werden beim Abziehen aus anderen Teilen herausgeschnitten.',
    wo: 'Rechts oben „Solid | Bohrung“ oder im Eigenschaften-Fenster. Tasten H / S.',
    s: ['Teil auswählen.', '<b>Bohrung</b> wählen — es wird rot durchsichtig.', 'Mit dem Körper zusammen auswählen und <b>⊖ Abziehen</b>.'] },
  { b: 'Formen & Teile', i: '🎨', t: 'Farbe & Transparent', k: 'farbe color eigene farbe transparent durchsichtig',
    was: 'Gibt Teilen eine Farbe — beim Mehrfarbdruck wird daraus je Farbe ein Filament.',
    wo: 'Rechts im Reiter SHAPES unter FARBE.',
    s: ['Teil auswählen.', 'Farbfeld anklicken oder „Eigene Farbe“.', '„Transparent“ macht es zum Hineinschauen durchsichtig (nur Anzeige).'] },
  { b: 'Formen & Teile', i: '🖼️', t: 'Bild einfügen', k: 'bild foto logo png jpg einfügen gravur relief',
    was: 'Foto oder Logo einfügen und auswählen, was daraus werden soll: Gravur, Leuchtrelief, Box, Ausstecher …',
    wo: 'V3D-CAD: Import → Bild. Oder Bild einfach ins Fenster ziehen.',
    s: ['„Bild“ anklicken und Datei wählen.', 'Gewünschte Verwendung aussuchen.'], run: '_imgInsert()' },
  { b: 'Formen & Teile', i: '⬆', t: 'Importieren (STL, STEP, 3MF, OBJ, SVG)', k: 'import importieren stl step 3mf obj svg datei laden groß großes modell scan vereinfachen dreiecke absturz',
    was: 'Fertige Modelle aus anderen Programmen oder von MakerWorld/Printables laden.',
    wo: '☰ Menü → Import, oder Datei ins Fenster ziehen.',
    s: ['☰ Menü → <b>Import</b>.', 'Datei wählen.', 'Sehr große Modelle (ab 300.000 Dreiecken, z. B. Scans): V3D CAD fragt nach — <b>Vereinfacht laden</b> (empfohlen, weicht höchstens etwa 0,01 mm ab) oder <b>Original laden</b>.'], tipp: 'STEP-Dateien behalten echte Kanten — ideal zum Weiterbearbeiten. Große Scans vereinfacht laden: Bearbeiten, Rückgängig und Speichern bleiben flott, im Druck sieht man keinen Unterschied.', run: 'doImport()' },
  { b: 'Formen & Teile', i: '🪄', t: 'Scan → CAD (1 Klick)', k: 'scan scannen gescannt umwandeln cad körper reverse engineering flächenrückführung automatisch einklick nachbauen',
    was: 'Macht aus einem gescannten Teil (STL, 3MF, OBJ oder PLY) automatisch einen echten CAD-Körper: Drehteil, Prisma mit Stufen und Bohrungen oder Freiform. Skizzen, Extrusionen und Drehungen stehen danach im Verlauf – Maße lassen sich ändern.',
    wo: 'Leiste Import → <b>🪄 Scan→CAD</b>, ☰ Menü → <b>🪄 Scan → CAD (1 Klick)</b> oder Suche „Scan“.',
    s: ['Scan auswählen (oder ohne Auswahl auf den Knopf tippen und die Datei wählen).', '<b>🪄 Scan→CAD</b> antippen – das Fenster zeigt, was gerade passiert (meist 1–2 Minuten).', 'Fertig: Der CAD-Körper steht an der Stelle des Scans, der Scan ist ausgeblendet (zum Vergleichen wieder einblenden). Rückgängig nimmt alles in einem Schritt zurück.'],
    tipp: '„Grob“ heißt: Das Teil passt zu keiner einfachen Bauart – dann Stellen von Hand nacharbeiten oder den Scan im Programm V3D Scan genauer bearbeiten.', run: '_scan2cad()' },
  { b: 'Formen & Teile', i: '🪄', t: 'Bauplan aus V3D Scan öffnen', k: 'bauplan v3d scan scannen scan reverse engineering nachbauen v3dcad json flächenrückführung',
    was: 'Ein Teil gescannt? <b>V3D Scan</b> macht daraus mit einem Klick einen CAD-Körper und speichert ihn als Bauplan (Datei <code>….v3dcad.json</code>). V3D CAD baut den Körper daraus Schritt für Schritt nach – mit Skizzen, Extrusionen und Drehungen, deren Maße du danach ändern kannst.',
    wo: '☰ Menü → <b>🪄 Bauplan aus V3D Scan öffnen</b>, oder die Datei über den normalen Import öffnen.',
    s: ['In V3D Scan: <b>🪄 Scan → CAD</b>, danach <b>⬇ Für V3D CAD</b>.', 'In V3D CAD: ☰ Menü → <b>🪄 Bauplan aus V3D Scan öffnen</b> und die Datei wählen.', 'Die Meldung zeigt, wie genau das Volumen zu V3D Scan passt. Rückgängig nimmt alles in einem Schritt zurück.'],
    tipp: 'Freiform-Teile (organische Formen) kommen als fester Körper ohne Verlauf – dafür gibt es keine Skizzen.', run: '_bauplanOeffnen()' },
  { b: 'Formen & Teile', i: '⬆', t: 'SVG importieren', k: 'svg import importieren vektor logo laser schriftzug extrudieren flach skizze datei',
    was: 'Vektor-Datei (Logo, Schriftzug, Laser-Vorlage) laden — als Körper extrudieren, flach aufsetzen oder als Skizze weiterbearbeiten.',
    wo: '☰ Menü → <b>SVG importieren</b>, in der Leiste Import → <b>SVG</b>, oder über den normalen Import.',
    s: ['<b>SVG importieren</b> anklicken und Datei wählen.', 'In der Vorschau Höhe/Größe einstellen.', '<b>✓ Importieren</b> oder <b>✎ Als Skizze</b>.'], run: '_svgImportOpen()' },
  { b: 'Formen & Teile', i: '🏷️', t: 'Text auf ein Teil bringen', k: 'text schrift beschriftung gravur erhaben namen',
    was: 'Schrift erhaben aufsetzen oder vertieft gravieren — auch auf Rundungen.',
    wo: 'Rechts „Körper hinzufügen“ → Text; für fertige Schilder: Generator „Namensschild“.',
    s: ['Text-Form hinzufügen und Text eintippen.', 'Auf das Teil ziehen.', 'Erhaben: Vereinen. Vertieft: als Bohrung markieren und Abziehen.'], video: 'namensschild' },

  // ── Skizze & Extrudieren ──────────────────────────────────────────────
  { b: 'Skizze & Extrudieren', i: '✏', t: 'Skizze zeichnen', k: 'skizze sketch zeichnen linie rechteck kreis bogen ellipse spline freihand trim ortho fang',
    was: 'Eine 2D-Zeichnung, aus der du einen Körper machst — der Weg wie in Fusion/Onshape.',
    wo: 'V3D-CAD: rechts „Werkzeuge öffnen“ → Skizze. V3D-SionCAD: Erstellen → Skizze.',
    s: ['Skizze öffnen — die Ansicht schaut von oben auf die Ebene.', 'Werkzeug wählen: <b>L</b> Linie, <b>R</b> Rechteck, <b>C</b> Kreis, <b>A</b> Bogen, <b>E</b> Ellipse, <b>F</b> Freihand.', 'Spline (<b>I</b>): Punkte setzen; Startpunkt wieder anklicken = geschlossen. Mit <b>↖ Auswahl</b> Punkte ziehen, <b>Alt+Klick</b> fügt einen ein, <b>Entf</b> löscht; <b>⌇ Kamm</b> zeigt die Krümmung.', 'Zahlen eintippen = genaue Maße. Ortho-Fang hält Linien gerade und rastet parallel (∥) oder senkrecht (⟂) zu vorhandenen Linien ein.', 'Konturen müssen geschlossen sein, damit daraus ein Körper werden kann.'], run: 'enterSketchMode()' },
  { b: 'Skizze & Extrudieren', i: '⛓', t: 'Abhängigkeiten & Bemaßen', k: 'abhängigkeiten constraints bemaßen bemaßung maß horizontal vertikal parallel senkrecht gleich koinzident tangential konzentrisch mittelpunkt kollinear symmetrisch fixieren freiheitsgrade vollständig bestimmt auswahl ziehen g2 g1 krümmungsstetig krümmung stetig spline übergang',
    was: 'Legt fest, wie Linien, Kreise und Bögen in der Skizze zueinander stehen, und gibt ihnen Maße. Ändert man ein Maß, passt sich die ganze Skizze an; zieht man an einer Ecke, bleiben alle Regeln erhalten.',
    wo: 'In der Skizze: Werkzeug „↖ Auswahl“ (S), daneben das Panel „⛓ Abhängigkeiten“.',
    s: ['Element oder Punkt mit <b>Auswahl (S)</b> anklicken, mit <b>Shift</b> weitere dazu.', 'Im Panel die Abhängigkeit wählen, z. B. <b>Parallel</b> oder <b>Tangential</b>. Oder erst den Knopf, dann die Elemente anklicken.', '<b>Bemaßen (M)</b>: Linie = Länge, Kreis = ⌀, Bogen = R, zwei Punkte = Abstand, zwei Linien = Winkel. Wert tippen + Enter.', 'Maßzahl in der Skizze anklicken = ändern. Ein Symbol (H, V, ∥ …) anklicken = Abhängigkeit entfernen.', '<b>G2</b> (krümmungsstetig): Spline + Nachbar anklicken, der Übergang wird ohne Knick und ohne Krümmungssprung.', 'Unten im Panel steht, wie viele Freiheitsgrade noch offen sind. Bei 0 ist die Skizze <b>vollständig bestimmt</b>.'], run: 'enterSketchMode(); _skSetTool(\'sel\')' },
  { b: 'Skizze & Extrudieren', i: '⬆', t: 'Extrudieren (Neu · Anfügen · Abziehen)', k: 'extrudieren extrusion höhe richtung symmetrisch zwei seiten anfügen abziehen automatisch durch alles',
    was: 'Macht aus der Skizze einen Körper. Automatisch erkennt V3D CAD, ob angefügt, abgezogen oder neu erzeugt wird — und zeigt es farbig an.',
    wo: 'In der Skizzenleiste: „✓ Extrudieren…“.',
    s: ['Skizze zeichnen, dann <b>✓ Extrudieren…</b>.', 'Richtung: eine Seite, symmetrisch oder zwei Seiten.', 'Abstand eintippen — negativ geht in die andere Richtung.', '<b>Ende</b>: Abstand, <b>Bis nächste Fläche</b>, <b>Bis Fläche…</b> (Zielfläche anklicken) oder <b>Durch alles</b>.', 'Optional <b>Kante oben/unten</b>: Rundung (Radius) oder Fase (Höhe × Breite; gleich = 45°).', 'Operation prüfen (blau neu, grün anfügen, rot abziehen, lila Schnittmenge) und OK.'] },
  { b: 'Skizze & Extrudieren', i: '▣', t: 'Mesh → CAD (STL bearbeitbar machen)', k: 'mesh to cad stl 3mf zurückführen rekonstruieren reverse engineering bohrung ändern skizze verlauf bearbeitbar',
    was: 'Macht aus einem importierten technischen Teil (STL/3MF) wieder ein bearbeitbares CAD-Teil mit Skizzen: Bohrungen werden Kreise, Kanten werden Linien und Bögen.',
    wo: 'Teil auswählen → Rechtsklick → „▣ Mesh → CAD“, oder Suche „Mesh → CAD“.',
    s: ['Importiertes Teil anklicken.', 'Rechtsklick → <b>▣ Mesh → CAD</b>. Der Bericht zeigt die Zahl der Schritte, Linien, Bögen und Kreise sowie die Abweichung.', 'Im Verlauf des neuen Teils eine Skizze öffnen, Maß ändern, <b>✓ Extrudieren…</b> → OK. Das Teil rechnet sich neu.', 'Geht bei Teilen mit senkrechten Wänden (Halter, Platten, Gehäuse), auch mit Querbohrungen, seitlichen Zapfen, Fasen beliebigen Winkels und gerundeten Kanten. Deckkanten stehen als „Kante oben/unten“ im Verlauf; gerundete senkrechte Kanten als Eckenrundung mit R-Maß in der Skizze (ein Wert ändert alle gleichen). Figuren und Scans bleiben Netze.'], run: 'meshToCad()' },
  { b: 'Skizze & Extrudieren', i: '〰', t: 'Prägen entlang Pfad (Nut/Steg)', k: 'prägen pfad nut steg rille v-nut rundnut dichtung kabelkanal zierlinie linie gravieren',
    was: 'Macht aus Linien, Bögen oder Splines der Skizze eine Nut oder einen Steg mit V-, Rund- oder Rechteckprofil.',
    wo: 'In der Skizzenleiste: „〰 Prägen entlang Pfad“.',
    s: ['Skizze auf die Fläche legen („▱ Auf Fläche“) und den Pfad zeichnen. Offene Linien und geschlossene Formen gehen beide.', '<b>〰 Prägen entlang Pfad</b>: vertieft (Nut) oder erhaben (Steg) wählen.', 'Profil (V, Rund, Rechteck), Breite und Tiefe eingeben, <b>✓ Prägen</b>.', 'Später ändern: im Baum die Prägung doppelklicken. Pfad und Maße lassen sich anpassen, das Teil rechnet sich neu.'], run: 'enterSketchMode()' },
  { b: 'Skizze & Extrudieren', i: '▦', t: 'Skizzenmuster (Lochreihe, Lochkreis)', k: 'muster pattern lochreihe lochkreis kreismuster linear vervielfachen kopien skizze',
    was: 'Vervielfacht Elemente der Skizze in einer Reihe oder auf einem Kreis. Die Kopien folgen der Vorlage, wenn du sie änderst.',
    wo: 'In der Skizze: „↖ Auswahl“, dann im Panel „▦ Muster…“.',
    s: ['Mit <b>↖ Auswahl (S)</b> die Vorlage(n) anklicken, z. B. eine Bohrung. Für einen Lochkreis zusätzlich den Mittelpunkt mitwählen (Shift).', '<b>▦ Muster…</b>: Linear (Anzahl, Abstand, Richtung) oder Kreis (Anzahl, Winkel, Mitte).', 'Vorlage bemaßen oder ziehen: Alle Kopien folgen.', '▦-Symbol anklicken = Muster ändern, Rechtsklick = lösen.'], run: 'enterSketchMode(); _skSetTool(\'sel\')' },
  { b: 'Skizze & Extrudieren', i: '∿', t: 'Spline auf der Fläche', k: 'spline auf fläche oberfläche kurve gewölbt kugel nut steg rille zierlinie 3d',
    was: 'Zeichnet eine Kurve direkt auf die Oberfläche eines Körpers, auch gewölbt, und macht daraus eine Nut oder einen Steg.',
    wo: 'Rechtsklick → „∿ Spline auf der Fläche“, oder Suche.',
    s: ['Punkte nacheinander auf das Modell klicken; die orange Linie zeigt die Kurve auf der Oberfläche.', 'Startpunkt erneut anklicken = geschlossen. Rücktaste nimmt den letzten Punkt weg.', 'Nut oder Steg, Profil, Breite und Tiefe wählen → <b>✓ Anwenden</b> (oder Enter).'], run: 'enterSplineOnSurface()' },
  { b: 'Skizze & Extrudieren', i: '🩹', t: 'Fläche löschen und heilen', k: 'fläche löschen heilen healing bohrung schließen loch zu zapfen entfernen rundung fase scharfe kante entfernen feature löschen',
    was: 'Entfernt eine Bohrung, einen Zapfen, eine Rundung oder eine Fase und schließt das Teil wieder sauber; Kanten werden wieder scharf.',
    wo: 'Rechtsklick → „🩹 Fläche löschen und heilen“, oder Suche.',
    s: ['Werkzeug starten und die Fläche anklicken (z. B. die Innenwand einer Bohrung oder eine gerundete Kante).', 'Im Fenster steht, was erkannt wurde, die Fläche ist orange markiert.', '<b>✓ Löschen und heilen</b> (oder Enter). Strg+Z macht es rückgängig.'], run: 'enterHealFace()' },
  { b: 'Anordnen', i: '⟿', t: 'Konturmuster & Kugelmuster', k: 'konturmuster kugelmuster muster kontur kante rändel kerben verteilen kugel noppen golfball',
    was: 'Verteilt einen Körper entlang einer Kante/Kontur (Konturmuster) oder gleichmäßig über eine Kugel (Kugelmuster), als Kopien oder gleich abgezogen/angefügt.',
    wo: 'Werkzeuge → „⟿ Konturmuster“ / „◍ Kugelmuster“, oder Suche.',
    s: ['Den Körper wählen, der verteilt werden soll (z. B. ein kleines Kerb-Werkzeug).', 'Konturmuster: eine Kante anklicken; die ganze Kantenkette wird genommen. Kugelmuster: die Kugel anklicken.', 'Anzahl, Teilung oder Auto (Lücke) einstellen; die Vorschau zeigt die Kopien.', 'Ergebnis: Kopien, vom Ziel abziehen oder an das Ziel anfügen → ✓ Erstellen.'], run: 'enterKonturmuster()' },
  { b: 'Skizze & Extrudieren', i: '⤳', t: 'Folgen (Profil entlang Kanten)', k: 'folgen sweep follow me profil kante pfad rand wulst nut leiste rohr gehrung',
    was: 'Zieht ein geschlossenes Profil entlang von Kanten des Modells, z. B. einen Rand rund um eine Box, einen Wulst am Becherrand oder eine Nut.',
    wo: 'In der Skizzenleiste „⤳ Folgen (Kanten)“, oder Suche „Folgen“.',
    s: ['Profil in einer Skizze zeichnen (am besten auf einer Fläche quer zur Kante) und <b>⤳ Folgen (Kanten)</b> drücken. Ohne Skizze: erst eine ebene Fläche als Profil anklicken.', 'Kante im Modell anklicken. Runde Kanten werden als ganze Kette gewählt, mit <b>Shift</b> weitere Kanten anhängen.', 'Operation wählen (automatisch, neu, anfügen, abziehen) und <b>Enter</b> oder <b>✓ Erstellen</b>.'], run: 'enterFolgen()' },
  { b: 'Skizze & Extrudieren', i: '⇕', t: 'Fläche ziehen / versetzen', k: 'push pull fläche ziehen versetzen offset drücken hinein tasche verlängern bis nächste',
    was: 'Eine ebene Fläche eines Körpers nach außen ziehen oder hineindrücken, exakt und auch bei runden oder schrägen Körpern.',
    wo: 'Rechtsklick → Fläche ziehen, oder Suche „Fläche ziehen“.',
    s: ['Fläche anklicken. Mit <b>Shift</b> weitere Flächen derselben Ebene dazu, dann <b>Enter</b>.', 'Die Kontur der Fläche erscheint als Skizze, das Extrudieren-Fenster ist offen.', 'Abstand eintippen: positiv = nach außen anfügen, negativ = hineindrücken.', 'Bei Bedarf <b>Ende</b> (z. B. Bis nächste Fläche) oder Operation ändern, dann OK.'], run: 'enterPushPull()' },
  { b: 'Skizze & Extrudieren', i: '▱', t: 'Skizze auf einer Fläche', k: 'skizze fläche oberseite auf fläche tasche',
    was: 'Zeichnet direkt auf eine Fläche eines Teils, z. B. auf die Oberseite einer Box — für Taschen, Löcher oder Aufbauten.',
    wo: 'In der Skizzenleiste „▱ Auf Fläche“ — oder vorher eine Arbeitsebene setzen.',
    s: ['Skizze öffnen, <b>▱ Auf Fläche</b> klicken.', 'Ebene Fläche des Teils anklicken.', 'Zeichnen und extrudieren — nach innen = Tasche/Loch, nach außen = anfügen.'] },
  { b: 'Skizze & Extrudieren', i: '🕳️', t: 'Loch ziehen', k: 'loch bohrung ziehen sackloch durchgangsloch tasche kreis p',
    was: 'Der schnellste Weg zu einem Loch: Fläche anklicken, Kreis zeichnen, in den Körper ziehen.',
    wo: 'V3D-CAD: „Werkzeuge öffnen“ → Loch ziehen. In jeder Skizze auch mit ⬆ Ziehen (P).',
    s: ['Fläche anklicken, in die das Loch soll.', 'Kreis zeichnen (Mitte klicken, dann am Rand).', 'In den Kreis klicken und <b>nach unten</b> ziehen — Tiefe live oder eintippen.', '<b>D</b> = Durchgangsloch („durch alles“).'], tipp: 'Danach direkt „🔩 Gewinde an Fläche“ — schon ist ein Gewindeloch fertig.', run: '_holeQuickStart()', video: 'loch-ziehen' },
  { b: 'Skizze & Extrudieren', i: '🕳️', t: 'Loch vertiefen', k: 'loch vertiefen tiefer bohrung sackloch tiefe messen ausmessen restwand',
    was: 'Ein vorhandenes Sackloch tiefer machen – auch an importierten STL-Teilen. Ø, Tiefe und Material unter dem Boden werden automatisch gemessen.',
    wo: 'V3D-CAD: „Werkzeuge öffnen“ → Loch vertiefen. V3D-SionCAD: Erstellen → Vertiefen. Oder Strg+K „vertiefen“.',
    s: ['In das Loch klicken – auf die Innenwand oder den Boden.', 'Im Fenster stehen Ø, jetzige Tiefe und Restmaterial.', 'Neue Tiefe eintippen oder +1/+2/+5/+10 bzw. „max.“ wählen – orange = neuer Teil.', '<b>✓ Vertiefen</b> (Enter).'], tipp: 'Rot/gelb heißt: Wand wird zu dünn oder bricht durch. Strg+Z macht alles rückgängig.', run: '_lvtStart()' },
  { b: 'Skizze & Extrudieren', i: '🕘', t: 'Skizze nachträglich ändern (Verlauf)', k: 'verlauf historie parametrisch skizze ändern nachträglich bearbeiten neu berechnen browser',
    was: 'Jedes Teil merkt sich seine Skizzen und Gewinde. Ändere später z. B. ein Loch von Ø8 auf Ø10 — das Teil rechnet sich mit allen späteren Schritten neu.',
    wo: 'Reiter ELEMENTE (in V3D-SionCAD: Browser links) — unter dem Teil stehen seine Schritte.',
    s: ['Teil in der Liste suchen, darunter steht z. B. „✏ Skizze 1 · Abziehen 12 mm“.', '<b>Doppelklick</b> oder <b>✎</b> öffnet die Skizze bzw. das Gewinde wieder.', 'Ändern und bestätigen — fertig.', 'Das Auge zeigt die Skizzenlinien im Modell.'],
    tipp: 'Wurde das Teil danach anders verändert (z. B. Rundung, Textur), fragt V3D CAD vorher nach.' },
  { b: 'Skizze & Extrudieren', i: '⟲', t: 'Drehen (Rotationskörper)', k: 'drehen revolve rotation vase hülse profil achse',
    was: 'Ein Profil um eine Achse drehen — für Vasen, Hülsen, Knöpfe und alles Runde.',
    wo: 'V3D-CAD: „Werkzeuge öffnen“ → Drehen. V3D-SionCAD: Erstellen → Drehen.',
    s: ['Halbes Profil neben der Achse zeichnen.', 'Winkel einstellen (360° = rundum).', 'Übernehmen.'], run: 'enterRevolveMode()' },
  { b: 'Skizze & Extrudieren', i: '⤧', t: 'Loft & Sweep', k: 'loft sweep übergang pfad rohr profil verbinden loft entlang pfad führung führungslinie kurve bogen bauchig',
    was: 'Loft verbindet zwei oder mehr Flächen weich miteinander. Sweep zieht ein Profil entlang eines Pfads (z. B. Rohr entlang einer Kurve).',
    wo: 'Loft: „Werkzeuge öffnen“ bzw. Erstellen → Loft. Sweep: in der Skizzenleiste.',
    s: ['Loft: Flächen nacheinander anklicken (Reihenfolge = Verlauf), Enter.', 'Loft entlang Pfad: nach den Flächen <b>⤳ Pfad</b> und die Kante(n) anklicken, denen der Übergang folgen soll.', 'Führungslinien: <b>〰 Führung</b> und Kanten anklicken, die vom ersten zum letzten Profil laufen; die Seitenform folgt ihnen.', 'Sweep: siehe „Skizze entlang Pfad“.'], run: 'enterLoftMode()' },
  { b: 'Skizze & Extrudieren', i: '↝', t: 'Skizze entlang Pfad (Sweep)', k: 'sweep entlang pfad hilfslinie kabelkanal leitung rohr ring gehrung querschnitt profil hohl kanal rahmen anstieg rampe steigung wendel spirale windungen helix',
    was: 'Zieht einen Querschnitt an einem Pfad entlang: ein Kabelkanal, der um die Ecke geht, eine Leitung, ein Ring um ein Sechseck. Ecken aus geraden Stücken werden eine Gehrung, Bögen bleiben glatt, die Wand ist überall gleich dick.',
    wo: 'In der Skizzenleiste: „┄ Hilfslinie“ (Taste H) und „↝ Entlang Pfad…“.',
    s: ['<b>Querschnitt</b> als geschlossenen Umriss zeichnen, so wie du ihn vom Pfadanfang in Laufrichtung siehst: links/rechts = quer, oben = oben am Körper. Ein zweiter Umriss darin macht ihn <b>hohl</b>.', '<b>┄ Hilfslinie</b> (H) einschalten und den <b>Pfad</b> zeichnen: Linien, Bögen oder Splines, eine zusammenhängende Kette, offen oder geschlossen (= Ring). Hilfslinien werden nie selbst zum Körper.', 'Den Querschnitt an das Ende legen, wo der Pfad beginnen soll. <b>↝ Entlang Pfad…</b>: Vorschau prüfen, <b>Lage</b> (Auf, Eingesenkt, Mittig) und <b>Operation</b> wählen (Automatisch, Neuer Körper, Anfügen, Abziehen, Schnittmenge, Loch-Körper), ✓ OK.', '<b>Ansteigen lassen:</b> bei <b>Anstieg</b> die Höhe am Ende in mm eintragen (Rampe, Kanal über eine Stufe), „weich“ = flacher Anfang und flaches Ende. Geschlossener Pfad: <b>Höhe gesamt</b> und <b>Windungen</b> → Wendel/Spirale.', 'Nut oder Kabelkanal in eine Platte: Skizze mit „▱ Auf Fläche“ auf die Oberseite legen, Lage <b>Eingesenkt</b>. Die Automatik zieht dann ab. Lage <b>Auf</b> auf einer Fläche fügt eine Leiste an.', 'Später ändern: im Baum „↝ Pfad-Skizze“ doppelklicken, Querschnitt oder Pfad anpassen, wieder „↝ Entlang Pfad…“ – das Teil rechnet sich neu.'],
    tipp: 'Schon gezeichnete Linien machst du im Auswahl-Werkzeug zur Hilfslinie: anklicken, dann „┄ Hilfslinie“. Ist der Querschnitt für eine enge Kurve zu breit, sagt das Fenster es dir.', run: 'enterSketchMode()' },
  { b: 'Skizze & Extrudieren', i: '📐', t: 'DXF, SVG & Bild-Vorlage in der Skizze', k: 'dxf svg laden speichern vorlage nachzeichnen abpausen laser plotter',
    was: 'Zeichnungen laden und weiterbearbeiten, eine Skizze als DXF speichern oder ein Bild als Vorlage zum Nachzeichnen unterlegen.',
    wo: 'In der Skizzenleiste: ⬆ DXF laden · ⬆ SVG laden · ⬇ DXF speichern · 🖼 Vorlage zum Nachzeichnen.',
    s: ['Skizze öffnen.', 'Entsprechenden Knopf wählen und Datei auswählen.'] },

  // ── Kombinieren ────────────────────────────────────────────────────────
  { b: 'Kombinieren', i: '∪', t: 'Vereinen', k: 'vereinen union verschmelzen zusammenfügen',
    was: 'Macht aus mehreren Teilen ein einziges.',
    wo: 'Kombinieren → ∪ Vereinen.',
    s: ['Alle Teile auswählen (Shift + Klick).', '<b>∪ Vereinen</b>.'], run: 'unionSelected()' },
  { b: 'Kombinieren', i: '⊖', t: 'Abziehen', k: 'abziehen subtrahieren loch bohrung ausschneiden',
    was: 'Schneidet Bohrungen aus Körpern heraus.',
    wo: 'Kombinieren → ⊖ Abziehen.',
    s: ['Die Form, die herausgeschnitten werden soll, als <b>Bohrung</b> markieren.', 'Bohrung und Körper zusammen auswählen.', '<b>⊖ Abziehen</b>.'], run: 'subtractHoles()' },
  { b: 'Kombinieren', i: '⋂', t: 'Schnittmenge', k: 'schnittmenge intersect überlappung',
    was: 'Übrig bleibt nur der Bereich, in dem sich alle ausgewählten Teile überlappen.',
    wo: 'Kombinieren → ⋂ Schnittmenge.', s: ['Mindestens zwei Teile auswählen.', '<b>⋂ Schnittmenge</b>.'], run: 'intersectSelected()' },
  { b: 'Kombinieren', i: '⊞', t: 'Gruppe & Aufheben', k: 'gruppe gruppieren aufheben zerlegen strg g',
    was: 'Gruppen bewegen sich gemeinsam, bleiben aber getrennte Teile. „Aufheben“ zerlegt auch ein Teil aus mehreren getrennten Stücken.',
    wo: 'Kombinieren → ⊞ Gruppe / ⊟ Aufheben. Strg+G.', s: ['Teile auswählen.', '<b>⊞ Gruppe</b> — zum Trennen <b>⊟ Aufheben</b>.'] },
  { b: 'Kombinieren', i: '✎', t: 'Operation bearbeiten', k: 'operation bearbeiten auflösen verlauf vereinen abziehen rückgängig machen',
    was: 'Löst ein Vereinen/Abziehen wieder in die ursprünglichen Teile auf — z. B. um eine Bohrung zu verschieben.',
    wo: 'Eigenschaften-Fenster des Ergebnisses → „✎ Operation bearbeiten“ bzw. „🕘 Verlauf“.',
    s: ['Ergebnis auswählen.', '„✎ Operation bearbeiten“.', 'Teile anpassen und erneut kombinieren.'] },

  // ── Anordnen ───────────────────────────────────────────────────────────
  { b: 'Anordnen', i: '⊜', t: 'Ausrichten', k: 'ausrichten align bündig mitte kante l',
    was: 'Teile bündig an Kanten oder mittig zueinander ausrichten.',
    wo: 'Anordnen → ⊜ Ausrichten (L).', s: ['Teile auswählen.', '<b>⊜ Ausrichten</b> und einen der Ausricht-Punkte anklicken.'], run: 'alignTool()' },
  { b: 'Anordnen', i: '⊿', t: 'Spiegeln', k: 'spiegeln mirror x y z m',
    was: 'Spiegelt ein Teil an der X-, Y- oder Z-Achse.',
    wo: 'Anordnen → ⊿ Spiegeln (M).', s: ['Teil auswählen.', '<b>⊿ Spiegeln</b>, dann X, Y oder Z.'], run: 'mirrorTool()' },
  { b: 'Anordnen', i: '⬓', t: 'Fläche unten, Aufstellen, Auto', k: 'fläche unten aufstellen auto ausrichten druck orientierung boden',
    was: 'Bringt Teile in eine gute Drucklage: eine bestimmte Fläche nach unten, die stabilste Standlage oder automatisch die beste Orientierung.',
    wo: 'Anordnen → ⬓ Fläche unten / ⊥ Aufstellen; Ansicht → 🔄 Auto.',
    s: ['Teil auswählen.', '<b>Fläche unten</b>: dann die Fläche anklicken, die auf die Platte soll.', '<b>Aufstellen</b>: nochmal klicken = nächste Standlage.'], run: 'toggleFaceDown()' },
  { b: 'Anordnen', i: '⋮', t: 'Muster (linear, Kreis, Waben)', k: 'muster linear kreismuster waben kopien anordnung pattern',
    was: 'Ein Teil mehrfach kopieren — in einer Reihe, im Kreis oder als Wabenmuster.',
    wo: 'Anordnen → ⋮ Linear / ⊙ Kreismuster / ⬡ Waben.', s: ['Teil auswählen.', 'Muster wählen, Anzahl und Abstand einstellen.'], run: 'linearPatternTool()' },
  { b: 'Anordnen', i: '▦', t: 'Platte füllen & mehrere Platten', k: 'füllen platte druckplatte kopien mehrere platten',
    was: 'So viele Kopien wie möglich auf die Druckplatte verteilen — oder weitere Druckplatten anlegen.',
    wo: 'Anordnen → ▦ Füllen / ▭ + Platte; unten in der Mitte die Platten-Leiste.', s: ['Teil auswählen, <b>Füllen</b>.', 'Anzahl oder „so viele wie passen“ wählen.'], run: 'fillPlateTool()' },

  // ── Form ändern ────────────────────────────────────────────────────────
  { b: 'Form ändern', i: '⬡', t: 'Kanten runden & abschrägen', k: 'kanten runden fase abschrägen fillet chamfer alles abrunden',
    was: 'Macht Kanten rund oder schräg — angenehmer in der Hand und schöner im Druck.',
    wo: 'Eigenschaften-Fenster → „⬡ Kanten bearbeiten“ / „⬤ Alles abrunden“. V3D-SionCAD: Konstruieren → Kanten. Kanten lassen sich auch direkt am Teil anfassen.',
    s: ['Teil auswählen.', 'Kante anklicken — oder <b>☑ Alle Kanten</b> / <b>⬆ Obere Kanten</b>. Gerundete Bögen werden mit einem Klick ganz gewählt.', 'Griff ziehen: nach links Fase, nach rechts Rundung — Maß danach eintippen.', 'Fase schräger oder steiler: <b>Fasen-Winkel</b> vorher einstellen (45° = gleichmäßig).', 'Unter <b>Kantenbearbeitungen</b> jede Fase/Rundung einzeln <b>ändern</b> oder <b>zurücknehmen</b>.'],
    tipp: 'Obere Kanten eignen sich für Ausstechformen, Deckel und Schilder. An einer Ecke besser nur Rundungen oder nur Fasen verwenden.', run: 'enterEdgeMode()' },
  { b: 'Skizze & Extrudieren', i: '╭', t: 'Ecke runden / fasen (Skizze)', k: 'skizze ecke runden fasen abrunden radius fillet chamfer ecken',
    was: 'Rundet oder fast einzelne Ecken im gezeichneten Umriss — schon bevor daraus ein Körper wird.',
    wo: 'In der Skizzenleiste „╭ Ecke runden“ bzw. „◸ Ecke fasen“.',
    s: ['Werkzeug wählen.', 'Maß im Feld am Zeiger tippen und Enter.', 'Ecken anklicken, an denen zwei Linien zusammenstoßen (auch Knicke von SVG-Umrissen).', 'Strg+Z nimmt die letzte Ecke zurück.'], run: 'enterSketchMode()' },
  { b: 'Form ändern', i: '⇕', t: 'Fläche ziehen (Push/Pull)', k: 'fläche ziehen push pull drücken verlängern',
    was: 'Eine Fläche nach außen ziehen oder hineindrücken — das Teil wird an dieser Stelle länger oder kürzer.',
    wo: 'V3D-SionCAD: Konstruieren → Fläche ziehen. Sonst über die Suche.', s: ['Fläche anklicken.', 'Ziehen oder Wert eintippen.'], run: 'enterPushPull()' },
  { b: 'Form ändern', i: '▢', t: 'Aushöhlen (Schale / Gehäuse)', k: 'aushöhlen schale gehäuse wandstärke hohl',
    was: 'Macht ein Teil hohl mit einstellbarer Wandstärke — eine Fläche kann offen bleiben.',
    wo: 'Eigenschaften-Fenster → „Gehäuse (aushöhlen)“. V3D-SionCAD: Konstruieren → Schale.', s: ['Teil auswählen.', 'Offene Fläche anklicken, Wandstärke wählen.'], run: 'enterShellMode()' },
  { b: 'Form ändern', i: '🎃', t: 'Kürbis schnitzen (eigener Scan)', k: 'kürbis kuerbis schnitzen scan gescannt echter eigener gesicht halloween aushöhlen hohl teelicht laterne import stl obj 3mf ply',
    was: 'Schnitzt ein Kürbis-Gesicht in einen echten, eingescannten Kürbis (oder jedes andere Teil). Vertieft bleibt der Kürbis voll; „Durchbrochen + hohl“ höhlt ihn mit gleichmäßiger Wand aus, macht unten ein Loch für ein LED-Teelicht und schneidet das Gesicht durch die Wand. Undichte Scans werden dabei automatisch repariert.',
    wo: 'Scan importieren und anklicken → unten links im Schnellmenü <b>🎃</b>. Oder im Kürbis-Generator ganz oben „🎃 Gewählten Kürbis schnitzen…“, oder in der Suche „Kürbis schnitzen“.',
    s: ['Den gescannten Kürbis importieren und <b>anklicken</b>.', 'Auf <b>🎃</b> klicken (Schnellmenü unten links).', 'Ein <b>Gesicht</b> wählen und mit <b>Größe</b>, <b>Höhe</b> und <b>Drehung</b> so schieben, dass die dunkle Vorschau richtig sitzt.', '<b>⬇ Vertieft</b> (Tiefe in mm) oder <b>💡 Durchbrochen + hohl</b> (Wand und Boden-Loch) wählen.', 'Auf <b>✓ Schnitzen</b> klicken – dauert ein paar Sekunden. Falsch? <b>Rückgängig</b>.'],
    tipp: 'Hohle Kürbisse mit dem Loch nach unten drucken. Nur ein LED-Teelicht hinein, keine echte Kerze! Bei großen Scans kann das Rechnen bis zu einer halben Minute dauern.', run: '_ksnOpen()' },
  { b: 'Form ändern', i: '✂', t: 'Schneiden (mit Verbindern)', k: 'schneiden teilen zerteilen schnittebene stift schwalbenschwanz verbinder zu groß',
    was: 'Teilt ein großes Teil mit einer Schnittebene — z. B. wenn es nicht auf die Platte passt. Auf Wunsch mit Stiften, Schwalbenschwanz oder Gewinde zum Zusammenstecken.',
    wo: 'Form ändern → ✂ Schneiden.', s: ['Teil auswählen, <b>Schneiden</b>.', 'Ebene verschieben/drehen.', 'Verbinder wählen und schneiden.'], run: 'openCutTool()' },
  { b: 'Drucken & Export', i: '🦈', t: 'Stützfinnen', k: 'stützfinnen finnen stützen stützstrukturen support überhang abbrechen pad zinken lage drucken ohne stützen printfins rippe stabilisierung festigkeit zug hebel belastung stark schichten',
    was: 'Baut abbrechbare Stützen fest ins Modell: dünne Wände (Finnen), die mit einlagigen Zinken am Teil haften und auf einem Bett-Pad stehen. Gedruckt wird dann ohne Slicer-Stützen, in jedem Slicer und auf jedem Drucker. Liegende oder schräge Lagen, die sonst viele Stützen bräuchten, werden so druckbar und oft deutlich stabiler.',
    wo: 'Anordnen → 🦈 Stützfinnen (neben ⊥ Aufstellen), oder Suche „Stützfinnen“.',
    s: ['Genau ein Teil auswählen, <b>🦈 Stützfinnen</b>. Rot = Überhänge, die Stütze brauchen.', 'Optional <b>🧭 Lage vorschlagen</b> (nochmal klicken = nächster Vorschlag) oder von Hand drehen und <b>↻ Neu berechnen</b>.', 'Platzierung wählen (Automatisch / Volle Abdeckung / Nur Wände), Düse und Schichthöhe wie im Slicer einstellen.', 'Hohes, schlankes Teil: <b>🦴 Rippe anklicken</b> und eine senkrechte Seite anklicken (oben = volle Höhe).', 'Wird das Teil belastet? Unter <b>💪 Festigkeit</b> Zug oder Hebel und die Kraftrichtung wählen, dann <b>Stärkste druckbare Lage</b>.', 'Fehlt irgendwo eine Finne: <b>✏️ Wand zeichnen</b>, Anfang und Ende auf der Unterseite des Überhangs anklicken (Ansicht von unten). Mit Modus <b>✏️ Von Hand</b> gibt es nur deine Wände.', '<b>✓ Finnen erzeugen</b>. Teil und Finnen zusammen exportieren, im Slicer Stützstrukturen AUS.'],
    tipp: 'Bricht die Finne schwer ab: Abstand etwas größer (PETG 0,25–0,3 mm). Hält sie nicht: Halt Richtung „fest“ oder Bett-Pad „Sicherer Halt“.', run: '_sfnOpen()' },
  { b: 'Form ändern', i: '🪄', t: 'Biegen', k: 'biegen krümmen radius kuppel rundung anlegen',
    was: 'Biegt ein Teil auf einen Radius — z. B. damit es sich an eine Tasse oder ein Rohr schmiegt.',
    wo: 'Form ändern → 🪄 Biegen.', s: ['Teil auswählen, <b>Biegen</b>.', 'Radius einstellen oder „Runde Wand anklicken“.'], run: '_bndOpen()' },
  { b: 'Form ändern', i: '⧈', t: 'Spielraum (Toleranz)', k: 'spielraum toleranz passung aufblasen schrumpfen offset deckel klemmt',
    was: 'Macht ein Teil um ±mm größer oder kleiner — für Passungen, z. B. −0,2 mm, wenn ein Deckel klemmt.',
    wo: 'Form ändern → ⧈ Spielraum.', s: ['Teil auswählen.', 'Wert in mm eingeben (minus = kleiner).'], run: 'openOffsetTool()' },
  { b: 'Form ändern', i: '🩹', t: 'Reparieren, Löcher schließen, Vereinfachen', k: 'reparieren wasserdicht löcher schließen stopfen vereinfachen dreiecke reduzieren',
    was: 'Macht kaputte Importe wieder druckbar und reduziert zu viele Dreiecke.',
    wo: 'Form ändern → 🩹 Reparieren / 🔻 Vereinfachen; Suche: „Löcher verschließen“.', s: ['Teil auswählen.', 'Reparieren bzw. Vereinfachen wählen.'], run: 'repairSelected()' },
  { b: 'Form ändern', i: '🖌️', t: 'Modellieren & Radierer', k: 'modellieren sculpt pinsel radierer entfernen glätten',
    was: 'Mit dem Pinsel Beulen aufbauen, abtragen und glätten — oder Bereiche wegradieren.',
    wo: 'Form ändern → 🖌️ Modellieren / 🧽 Radierer.', s: ['Werkzeug wählen.', 'Mit gedrückter Maus über das Teil fahren (Radius per Mausrad, Shift = glätten).'], run: 'openSculptTool()' },

  // ── Gewinde & Bewegung ────────────────────────────────────────────────
  { b: 'Gewinde & Bewegung', i: '🔩', t: 'Gewinde an Fläche', k: 'gewinde thread innengewinde außengewinde m3 m4 m5 m6 m8 m10 m12 spiel toleranz bohrung zylinder',
    was: 'Setzt ein Gewinde in eine vorhandene Bohrung (innen) oder auf einen Zylinder (außen). Die passende Normgröße wird erkannt, z. B. Ø10-Loch → M12.',
    wo: 'V3D-CAD: „Werkzeuge öffnen“ → Gewinde an Fläche. V3D-SionCAD: Erstellen → Gewinde.',
    s: ['Bohrung oder Zylinder anklicken.', 'Größe, Steigung, Länge, Rechts/Links prüfen.', '<b>Druck-Spiel</b> wählen (typisch +0,2 … 0,3 mm für gedruckte Teile).', '„✓ Gewinde schneiden“.'],
    tipp: 'Später ändern: in der Elemente-Liste unter dem Teil „🔩 Gewinde …“ doppelklicken.', run: '_thfStart()' },
  { b: 'Gewinde & Bewegung', i: '🔗', t: 'Beweglich machen (FlexiGen)', k: 'flexi flexigen beweglich gelenk scharnier glieder print in place biegen',
    was: 'Schneidet ein flaches Teil (Herz, Schild, Tier) in Glieder mit Fass-Scharnieren. Druckt flach am Stück, ohne Stützen, und biegt sich danach.',
    wo: '„Werkzeuge öffnen“ → Beweglich (Flexi). V3D-SionCAD: Erstellen → Flexi.',
    s: ['Ein flaches Teil auswählen (2,5–30 mm dick).', 'Anzahl der Glieder und Spiel wählen.', '„Flexi-Modell bauen“, mit „Biegen“ ausprobieren.', '„✓ Übernehmen“.'], run: '_flxOpen()' },
  { b: 'Gewinde & Bewegung', i: '🔧', t: 'Schrauben, Muttern, Gewindedosen', k: 'schraube mutter din norm schraubdose deckel gewindeloch',
    was: 'Fertige Normteile und Schraubverbindungen als Generator.',
    wo: 'GENERATOREN → Schraube / Mutter, Schraubenloch, Schraubdose.', s: ['Generator öffnen, Größe und Länge wählen, Erstellen.'], run: '_openScrewModal()' },

  // ── Oberfläche & Aussehen ─────────────────────────────────────────────
  { b: 'Oberfläche & Aussehen', i: '▦', t: 'Textur', k: 'textur muster oberfläche waben riffel holz rauschen eingeprägt flächen wählen',
    was: 'Prägt ein Muster in die Oberfläche (Waben, Riffel, Holz …). Die Außenmaße bleiben, der Boden bleibt glatt.',
    wo: 'Eigenschaften-Fenster → Textur. V3D-SionCAD: Konstruieren → Textur.',
    s: ['Teil auswählen, Textur öffnen, Muster wählen.', 'Höhe und Skalierung einstellen.', 'Ort: Außen/Oben/Innen/Unten — oder <b>👆 Flächen wählen</b> und einzelne Flächen anklicken (z. B. nur den Zylindermantel).'], run: 'toggleTexPanel()' },
  { b: 'Oberfläche & Aussehen', i: '⬡', t: 'Muster auf Rundung', k: 'muster rundung vase durchbrochen voronoi waben relief',
    was: 'Legt ein Relief- oder durchbrochenes Muster auf runde Teile wie Vasen, Becher oder Lampenschirme.',
    wo: 'Suche „Muster auf Rundung“ oder im Textur-Fenster.', s: ['Rundes Teil auswählen.', 'Muster wählen: Relief oder durchbrochen.'], run: '_rmpOpen()' },
  { b: 'Oberfläche & Aussehen', i: '🖍️', t: 'Mehrfarb-Druck & Bemalen', k: 'mehrfarb druck ams farbe bemalen pinsel filament 3mf',
    was: 'Mehrfarb-Druck: Flächen filamentgenau einfärben wie in Bambu Studio, Export als 3MF. Bemalen: Farben frei aufmalen (nur Anzeige).',
    wo: 'Form ändern → 🖍️ Mehrfarb-Druck / 🎨 Bemalen.', s: ['Teil auswählen, Werkzeug öffnen.', 'Farbe wählen und Flächen anmalen.'], run: 'openMmuPaintTool()' },
  { b: 'Oberfläche & Aussehen', i: '✨', t: 'Aussehen (Material)', k: 'aussehen material matt glänzend silk metall chrom keramik gummi glas',
    was: 'Zeigt Teile wie aus matt, glänzend, Silk-PLA, Metall, Chrom, Keramik, Gummi oder Glas. Nur Anzeige — Farbe und Export bleiben.',
    wo: 'Rechts unter FARBE → „Aussehen“.', s: ['Teil auswählen.', 'Aussehen im Auswahlfeld wählen.'] },
  { b: 'Oberfläche & Aussehen', i: '🎬', t: 'Render-Studio: Foto & Video', k: 'foto bild render rendern png jpg werbung shop transparent 4k video 360 drehteller turntable mp4 kamerafahrt ansichten zip wasserzeichen reel tiktok instagram',
    was: 'Macht schöne Fotos und Videos von deinem Modell — für Kunden, Shop und Werbung: einzelne Fotos (bis 4K, auch transparent, 9:16 bis 1:1), alle Ansichten auf einmal als ZIP, ein 360°-Drehteller-Video oder eine Kamerafahrt durch gemerkte Ansichten (MP4). Auf Wunsch mit Wasserzeichen.',
    wo: 'Rechts unter FARBE → „🎬 Foto & Video“, oder Export ▾ → „Render-Studio“.', s: ['Oben die Art wählen: 📷 Foto, 🖼️ Ansichten, 🔄 360° oder 🛤️ Fahrt.', 'Licht, Hintergrund und Größe wählen, bei Bedarf ein Wasserzeichen eintippen (z. B. „© Volme 3D“).', 'Foto: Blickwinkel einstellen, „📷 Foto erstellen“. 360°: Neigung über die Ansicht wählen, Dauer einstellen, „🎬 Video rendern“.', 'Fahrt: Ansicht einstellen → „＋ Aktuelle Ansicht merken“, für jeden Punkt wiederholen (mind. 2), dann „🎬 Video rendern“.', 'Mit „⬇“ speichern.'],
    tipp: 'Im Video kreist das Wasserzeichen langsam ums Bild – so lässt es sich kaum wegschneiden. Für Reels und TikTok die Größe 9:16 nehmen.', run: '_fotoOpen()' },

  // ── Generatoren ────────────────────────────────────────────────────────
  { b: 'Generatoren', i: '✨', t: 'Generatoren', k: 'generatoren generator vorlagen vase lampe dino schiff zahnrad box qr kranz',
    was: 'Fertige, einstellbare Modelle: Vasen, Lampen, Zahnräder, Boxen, Schilder, Dinos, Schiffe, Kränze und vieles mehr — einfach Werte einstellen und erstellen.',
    wo: 'Oben Reiter <b>GENERATOREN</b> (ganze Seite mit Suche und A–Z) oder rechts „Generatoren ▾“.',
    s: ['GENERATOREN öffnen.', 'Suchen (Wort oder Anfangsbuchstabe) oder nach Thema stöbern.', 'Karte anklicken, einstellen, „Erstellen“.', 'Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.'], run: '_genPageOpen()', video: 'vase' },
  { b: 'Generatoren', i: '🤖', t: 'KI-Modell', k: 'ki künstliche intelligenz text bild 3d erzeugen',
    was: 'Erzeugt ein 3D-Modell aus einer Textbeschreibung.',
    wo: 'GENERATOREN → KI-Modell.', s: ['Beschreibung eintippen.', 'Erzeugen und warten.'], run: 'kiTogglePanel()' },

  // ── Prüfen ─────────────────────────────────────────────────────────────
  { b: 'Prüfen', i: '📐', t: 'Messen', k: 'messen abstand durchmesser maß lineal',
    was: 'Misst Abstände und Durchmesser in mm.',
    wo: 'Prüfen → 📐 Messen, oder Rechtsklick → Messen.', s: ['Messen starten.', 'Kreiskante anklicken = Durchmesser, zwei Punkte = Abstand.', 'Esc beendet.'], run: 'measureTool()' },
  { b: 'Prüfen', i: '◪', t: 'Schnittansicht', k: 'schnitt schnittansicht aufschneiden innen wandstärke',
    was: 'Schneidet das Modell zum Hineinschauen auf — nur Ansicht, ändert nichts.',
    wo: 'Prüfen → ◪ Schnitt.', s: ['Schnitt starten.', 'Ebene verschieben/drehen.', 'Esc beendet.'], run: 'sectionTool()' },
  { b: 'Prüfen', i: '⧉', t: 'Passung prüfen', k: 'passung prüfen überschneidung abstand zusammen',
    was: 'Zeigt, ob sich zwei Teile überschneiden (rot) oder wie viel Luft dazwischen ist.',
    wo: 'Kombinieren → ⧉ Passung.', s: ['Zwei Teile auswählen.', '<b>⧉ Passung</b>.'], run: 'fitCheckTool()' },

  // ── Drucken & Export ──────────────────────────────────────────────────
  { b: 'Drucken & Export', i: '🖨', t: 'Druck-Vorschau & Slicer-Einstellungen', k: 'druck vorschau slicer drucker bambu snapmaker anycubic elegoo prusa filament schicht infill stützen gewicht zeit gcode',
    was: 'Drucker (über 560 Modelle) und Einstellungen wählen, sofort sehen, ob es passt und wie viel Material es braucht — dann im V3D Slicer echt slicen oder als Projekt-3MF an Bambu Studio, Orca, Anycubic, Snapmaker oder Elegoo geben.',
    wo: 'Prüfen → 🖨 Druck-Vorschau, oder Export ▾.',
    s: ['Hersteller und Drucker wählen, Filament, Schicht, Wände, Füllung, Stützen.', '„Slicen & Schichten ansehen“ = echte Druckzeit, Gewicht, Schichten, G-Code.', '„📦 Projekt-3MF“ = Datei für den eigenen Slicer mit allen Einstellungen.'], run: '_dvOpen()' },
  { b: 'Drucken & Export', i: '⬇', t: 'Exportieren (STL, 3MF, OBJ, STEP)', k: 'export exportieren stl 3mf obj step herunterladen pro körper',
    was: 'Speichert das Modell für Slicer oder andere CAD-Programme. Mehrfarbige Modelle gehen als 3MF.',
    wo: 'Oben rechts „⬇ Export“ (Pfeil ▾ für mehr Formate).', s: ['Optional Teile auswählen (sonst alles).', '<b>⬇ Export</b> oder Format im Menü ▾ wählen.'], run: 'exportSTL()' },
  { b: 'Drucken & Export', i: '🛰️', t: 'An Slicer senden / V3D Slicer', k: 'slicer senden v3d slicer bambu studio orca drucker flotte',
    was: 'Gibt das Modell direkt an den V3D Slicer oder deinen eigenen Slicer weiter.',
    wo: 'Export ▾ → „🖨 Im V3D Slicer öffnen“ bzw. Slicer-Einträge.', s: ['Export ▾ öffnen.', 'Ziel wählen.'], run: '_openInV3DSlicer()' },
  { b: 'Drucken & Export', i: '✂', t: 'Laser & CNC', k: 'laser svg dxf cnc fräsen gcode draufsicht',
    was: 'Draufsicht als SVG/DXF für den Laser, oder G-Code für eine CNC-Fräse aus einer Skizze.',
    wo: 'Suche „Laservorlage“ bzw. in der Skizzenleiste „🔧 CNC-Fräsen“.', s: ['Laservorlage öffnen oder Skizze → CNC-Fräsen.', 'Einstellungen wählen und speichern.'], run: '_lzOpen()' },

  // ── Datei & Hilfe ─────────────────────────────────────────────────────
  { b: 'Datei & Hilfe', i: '💾', t: 'Speichern, Öffnen, Meine Designs', k: 'speichern öffnen designs galerie neu strg s sicherungen',
    was: 'Designs speichern und wieder öffnen. Unter „🕘 Versionen“ holst du ältere Stände (bis 30 Tage) zurück oder hältst wichtige Stände fest.',
    wo: '☰ Menü → Speichern / Öffnen / Versionen; „📁 Meine Designs“.', s: ['<b>Strg+S</b> speichert.', '„📁 Meine Designs“ zeigt alle gespeicherten Designs.'], run: 'showDesigns()' },
  { b: 'Datei & Hilfe', i: '📚', t: 'Bibliothek', k: 'bibliothek heruntergeladen modelle durchsuchen öffnen drucken groß scan vereinfachen original',
    was: 'Heruntergeladene Modelle (STL/3MF/OBJ/STEP) durchsuchen, ansehen, öffnen und drucken.',
    wo: 'Import → 📚 Bibliothek.', s: ['Bibliothek öffnen und Modell wählen.', 'Sehr große Dateien (ab 300.000 Dreiecken, z. B. Scans) vereinfacht die Bibliothek einmalig von selbst – höchstens etwa 0,01 mm Abweichung. Das Original liegt danach im Ordner <b>Original</b>.'],
    tipp: 'Das automatische Vereinfachen braucht den Druck-Helfer ab Version 12 (Knopf „Helfer aktualisieren“ oben in der Bibliothek).', run: '_stlLibOpen()' },
  { b: 'Datei & Hilfe', i: '👥', t: 'Teilen & gemeinsam arbeiten', k: 'teilen link gemeinsam arbeiten mitsehen betreuer',
    was: 'Modell als 3D-Link teilen oder gemeinsam an einem Design arbeiten — der andere braucht kein Konto.',
    wo: '☰ Menü → 🔗 Teilen / 👥 Gemeinsam arbeiten.', s: ['Im ☰ Menü auswählen und Link weitergeben.'] },
  { b: 'Datei & Hilfe', i: '🎬', t: 'Videos, Kurse, Was ist neu', k: 'videos kurs lernen was ist neu changelog tastenkürzel hilfe',
    was: 'Kurze Howto-Videos, geführte Kurse, die Liste aller Neuerungen und alle Tastenkürzel.',
    wo: 'Oben „🎬 Videos“; ☰ Menü → Kurs / Tastenkürzel; Versionsknopf = Was ist neu.', s: ['Gewünschten Eintrag öffnen.'], run: '_howtoMenu()' },

  // ── Ergänzungen (Kleinfunktionen) ────────────────────────────────────
  { b: 'Erste Schritte', i: '⚙', t: 'Arbeitsbereich einstellen (Drucker, Bauplatte, Raster)', k: 'einstellungen arbeitsbereich bauplatte drucker größe raster fangraster magnet gizmo navigation',
    was: 'Legt die Größe der Bauplatte passend zu deinem Drucker fest (A1, P1S, H2C, Ender, Prusa, Kobra, Voron …) und stellt Fangraster, Andock-Magnet, Verschiebe-Pfeile und Maus-Empfindlichkeit ein.',
    wo: 'Unten rechts in der 3D-Ansicht: „Einstellungen“.',
    s: ['„Einstellungen“ öffnen.', 'Drucker wählen — die Bauplatte passt sich an (oder Breite × Tiefe eintippen).', 'Fangraster wählen: aus, 0,1 / 0,25 / 0,5 / 1 mm.'], run: '_openSceneSettings()' },
  { b: 'Erste Schritte', i: '✥', t: 'Exakt versetzen (mm-Schritte)', k: 'versetzen verschieben genau millimeter schritt nudge',
    was: 'Schiebt die Auswahl um eine genaue Strecke in eine Richtung — z. B. „5 mm nach rechts“.',
    wo: 'Suche (Strg+K) → „Exakt versetzen“. Alternativ Pfeiltasten (Shift = fein).',
    s: ['Teil auswählen.', '„Exakt versetzen“ öffnen.', 'Strecke in mm eintippen und Richtung anklicken.'], run: 'toggleNudge()' },
  { b: 'Erste Schritte', i: '🔒', t: 'Sperren & Ausblenden', k: 'sperren entsperren ausblenden einblenden verstecken auge strg l strg h',
    was: 'Gesperrte Teile lassen sich nicht versehentlich verschieben. Ausgeblendete Teile sind unsichtbar, bleiben aber im Design.',
    wo: 'Ansicht → 🔒 Sperren / 👁 Ausblenden; in der Elemente-Liste das Auge.',
    s: ['Teil auswählen.', '<b>Strg+L</b> sperren/entsperren, <b>Strg+H</b> ausblenden.', '<b>Strg+Shift+H</b> blendet alles wieder ein.'], run: 'toggleHideSelected()' },
  { b: 'Erste Schritte', i: '🔗', t: 'Freiform-Auswahl (Lasso)', k: 'lasso freiform auswahl umranden',
    was: 'Statt eines Rechtecks frei um die gewünschten Teile herum zeichnen.',
    wo: 'Suche (Strg+K) → „Freiform-Auswahl“.', s: ['Lasso einschalten.', 'Mit gedrückter Maus um die Teile herumfahren.'], run: 'toggleLasso()' },
  { b: 'Erste Schritte', i: '⟳', t: 'Turntable (Drehteller)', k: 'turntable drehteller drehen präsentation rundum',
    was: 'Lässt die Ansicht langsam um das Modell kreisen — schön zum Zeigen.',
    wo: 'Unten rechts „⟳ Turntable“ oder Taste T.', s: ['„Turntable“ anklicken.', 'Nochmal klicken stoppt.'], run: 'toggleTurntable()' },
  { b: 'Erste Schritte', i: '🎨', t: 'Vorlagen beim Start', k: 'start vorlagen galerie leeres design beginnen',
    was: 'Beim Öffnen fragt V3D CAD „Womit möchtest du starten?“ — leeres Design oder direkt ein Generator.',
    wo: 'Erscheint beim Start; jederzeit über die Suche „Vorlagen-Galerie“.', s: ['Karte anklicken — oder „Leeres Design“.', 'Häkchen unten: beim nächsten Start nicht mehr zeigen.'], run: 'showStarter()' },
  { b: 'Formen & Teile', i: '🥤', t: 'Rohr-Formen: Konisches Rohr, Kantrohr, Trichter', k: 'konisches rohr kantrohr trichter adapter reduzierstück hohlprofil',
    was: 'Konisches Rohr mit unterschiedlichen Durchmessern oben und unten (Adapter, Reduzierstück), eckiges Kantrohr und ein durchgehend offener Trichter.',
    wo: 'Rechts „Körper hinzufügen“ → Konisches Rohr / Kantrohr / Trichter.', s: ['Form hinzufügen.', 'Durchmesser, Wand und Höhe im Eigenschaften-Fenster einstellen.'], run: 'addConeTube()' },
  { b: 'Kombinieren', i: '🖇️', t: 'Stege neu berechnen', k: 'stege verbinden schwebende teile topper buchstaben brücke',
    was: 'Verbindet flache Teile, die sonst frei schweben würden (z. B. einzelne Topper-Buchstaben), über kürzeste Stege.',
    wo: 'Kombinieren → 🖇️ Stege.', s: ['Flache Teile auswählen.', '<b>Stege</b> — alte Stege in der Auswahl werden ersetzt.'], run: '_ttRebridge()' },
  { b: 'Prüfen', i: '✅', t: 'Druck-Check', k: 'druck check prüfen wasserdicht passt bett überhang export',
    was: 'Prüft vor dem Export: Ist das Teil wasserdicht, passt es aufs Bett, liegt es auf der Platte, gibt es kritische Überhänge?',
    wo: 'Suche (Strg+K) → „Druck-Check“.', s: ['Druck-Check öffnen.', 'Ampel lesen und Hinweise abarbeiten (z. B. Reparieren, Auf Boden).'], run: '_printCheckOpen()' },
  { b: 'Drucken & Export', i: '🔄', t: 'Für Druck ausrichten (Auto)', k: 'auto ausrichten orientierung druck stützen wenig überhang',
    was: 'Berechnet die beste Drucklage — so, dass möglichst wenig Stützen nötig sind (wie Bambu Studio).',
    wo: 'Ansicht → 🔄 Auto.', s: ['Teil auswählen (ohne Auswahl: alle).', '<b>🔄 Auto</b>.'], run: 'autoOrientForPrint()' },
  { b: 'Drucken & Export', i: '⬇', t: 'STL pro Körper', k: 'stl pro körper einzeln export teile getrennt',
    was: 'Speichert jedes Teil als eigene STL-Datei — praktisch, wenn Teile getrennt gedruckt werden.',
    wo: 'Export ▾ bzw. Suche „STL pro Körper“.', s: ['Teile auswählen (sonst alle).', '„STL pro Körper“ — jede Datei wird einzeln gespeichert.'], run: 'exportPartsSTL()' },
  { b: 'Datei & Hilfe', i: '🛟', t: 'Fernwartung & Gemeinsam arbeiten', k: 'fernwartung betreuer hilfe remote mitsehen gemeinsam stift',
    was: 'Gemeinsam arbeiten: ihr seht beide alles, bearbeiten darf einer — den Stift reicht ihr euch weiter. Fernwartung lädt ein Programm, mit dem dein Betreuer dir helfen kann.',
    wo: '☰ Menü → 👥 Gemeinsam arbeiten / 🛟 Fernwartung.', s: ['Im ☰ Menü auswählen.', 'Code bzw. Link an den Partner geben; jeder Zugriff muss bestätigt werden.'], run: '_mitOpen()' },
  { b: 'Datei & Hilfe', i: '🖱', t: 'SpaceMouse', k: 'spacemouse 3dconnexion 6dof navigation',
    was: 'Richtet eine 3D-Maus von 3Dconnexion zum Drehen und Verschieben der Ansicht ein.',
    wo: '☰ Menü → 🖱 SpaceMouse.', s: ['SpaceMouse anschließen.', 'Einrichtung öffnen und den Schritten folgen.'], run: 'openSpaceMouseSetup()' },
];

// ── Generatoren A–Z (je Generator ein Eintrag; Texte aus dem Code der Generator-Fenster erhoben) ──
window.V3D_HILFE.push(
  {"b": "Generatoren A–Z", "i": "💳", "t": "3D-Visitenkarte", "k": "visitenkarte karte portrait foto relief basrelief text tischaufsteller ständer kartenfach namensschild", "was": "Du bekommst eine Visitenkarte mit deinem Portraitfoto als flachem Basrelief und fühlbarem Text, alles in einem Stück. Als Tischaufsteller geht es auch mit Ständer und Kartenfach.", "wo": "Oben Reiter <b>GENERATOREN</b> → „3D-Visitenkarte“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Wähle die Bauart <b>Visitenkarte</b> oder <b>Tischaufsteller</b> und lade ein Portraitfoto.", "Leg die Fotoposition fest (<b>Links</b>, <b>Rechts</b>, <b>Ganz</b> oder <b>Ohne</b>) und stell <b>Relief-Tiefe</b>, <b>Plastik</b> und <b>Glättung</b> ein.", "Trag Name und Zeilen 2 bis 4 ein, wähle <b>Schrift</b> und <b>Erhaben</b> oder <b>Eingelassen</b> und stell <b>Name-Größe</b> und <b>Text-Höhe</b> ein.", "Wenn du willst, aktivier <b>Ständer mit Nut erzeugen</b> und <b>Kartenfach davor</b>. Klick dann auf <b>✓ Erstellen</b>."], "tipp": "Druck die Karte flach, mit dem Relief nach oben und ohne Stützen.", "run": "_vkOpen()"},
  {"b": "Generatoren A–Z", "i": "🔋", "t": "Batteriehalter", "k": "batteriehalter batterie akku aa aaa 18650 21700 cr123a zelle halter fach", "was": "Erzeugt einen Halter mit Mulden für Rundzellen wie AAA, AA, C, D, 18650, 21700 oder CR123A – zum sicheren Aufbewahren oder Einbauen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Batteriehalter“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["<b>Zelltyp</b> wählen, z. B. <b>AA</b> oder <b>18650</b>.", "Unter <b>Anordnung</b> <b>Zellen je Reihe</b> und <b>Reihen</b> einstellen.", "<b>Wandstärke</b> und <b>Boden</b> festlegen.", "Bei <b>Enden</b> <b>Geschlossen</b>, <b>Kontakt frei</b> oder <b>Offen</b> (Lötfahnen) wählen, dann <b>✓ Erstellen</b>."], "tipp": "Jede Mulde hat bereits 0,5 mm Spiel zur Zelle eingerechnet.", "run": "_openBattModal()"},
  {"b": "Generatoren A–Z", "i": "🥤", "t": "Becher", "k": "becher tasse stiftebecher zahnputzbecher henkel katze bär hase frosch name kinder geschenk", "was": "Ein Becher für Stifte, Pinsel oder Zahnbürsten: rund, sechseckig oder gewellt, mit oder ohne Henkel. Als Tier-Becher (Katze, Bär, Hase, Frosch) bekommt er Ohren am Rand und ein Gesicht. Dazu kommt auf Wunsch dein Name.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Becher“, Thema „Spielwelt & Kinder“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Vorlage</b> z. B. <b>✏️ Stiftebecher</b>, <b>☕ Tasse</b> oder ein Tier wählen.", "<b>Höhe</b>, <b>Durchmesser</b>, <b>Oben weiter</b> und <b>Wand</b> einstellen, <b>Form</b> und <b>Henkel</b> wählen.", "Bei <b>Name</b> den Namen eintippen, <b>Schrift</b> und <b>Name wo?</b> (vorne oder hinten) wählen.", "Farben wählen und <b>✓ Erstellen</b> klicken."], "tipp": "Druckt ohne Stützen, auch der Henkel (er hat 45°-Schrägen). Gedruckt ist der Becher nicht lebensmittelecht, also nicht zum Trinken.", "run": "_kgOpen('becher')"},
  {"b": "Generatoren A–Z", "i": "🛩️", "t": "Bausatz-Rahmen", "k": "bausatz rahmen gussrahmen gussast angüsse plastikmodell nummern teileliste bauanleitung kit", "was": "Deine ausgewählten Teile hängen an dünnen Angüssen in einem Gussrahmen, wie bei einem Plastikmodell. Jedes Teil hat ein Fähnchen mit Nummer, dazu gibt es eine Teileliste mit Rahmenplan.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Bausatz-Rahmen“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Alle Teile auswählen und vorher in die Drucklage bringen (z. B. mit ⬓ Fläche unten)", "Unter Rahmen <b>Stabdicke</b>, <b>Stabhöhe</b> und <b>Abstand zum Teil</b> einstellen", "Angüsse <b>2 je Teil</b> oder <b>4 je Teil</b> wählen und die <b>Stärke am Teil</b> setzen", "<b>Fähnchen mit Nummer an jedem Teil</b>, <b>Ziffernhöhe</b> und das <b>Druckbett</b> festlegen", "Auf <b>✓ Erzeugen</b> klicken"], "tipp": "Alles liegt unten auf dem Druckbett und druckt ohne Stützen. Passt nicht alles auf ein Bett, entstehen mehrere Rahmen A, B, …", "run": "_sprOpen()"},
  {"b": "Generatoren A–Z", "i": "🍺", "t": "Bierkasten", "k": "bierkasten kasten schnaps fläschchen flaschen stapelbar party geschenk fächer kurze", "was": "Du baust einen Mini-Bierkasten für Schnapsfläschchen mit Fächern und Grifflöchern. Auf Wunsch ist er stapelbar.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Bierkasten“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Wähle die <b>Flasche</b> (<b>2 cl</b>, <b>4 cl</b> oder <b>5 cl</b>) oder trag <b>Flaschen-Ø</b> und <b>Flaschenhöhe</b> selbst ein (am besten nachmessen).", "Wähle die <b>Fächer</b> (z. B. <b>3 × 4</b>) und als Trennung <b>Sterne</b> oder <b>Gitter</b>.", "Stell <b>Wand</b>, <b>Ecken</b> und die Höhe ein: <b>Höhe automatisch</b> oder <b>Höhe von Hand</b>.", "Wähle die <b>Grifflöcher</b> (<b>Halbrund</b> oder <b>Langloch</b>), dazu <b>Stapelbar</b> mit <b>Fußhöhe</b> und <b>Passung</b>.", "Klick auf <b>✓ Erstellen</b>."], "tipp": "Druck den Kasten aufrecht ohne Stützen, denn Fuß und Griffbögen tragen sich selbst. Für FDM passt eine Passung von 0,3–0,5 mm.", "run": "_bkxOpen()"},
  {"b": "Generatoren A–Z", "i": "🏮", "t": "Motivlicht", "k": "motivlicht windlicht lampe klötzchenlampe klötzchen schirm lampenschirm holz sockel teelicht led svg motiv wald hirsch häuser sterne schichten lithophane weihnachten", "was": "Du baust ein viereckiges Windlicht: oben ein dünner Schirm mit Motiven in Schichten, unten ein Sockel für Holz-Filament mit Mulde für ein LED-Teelicht.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Motivlicht“ (oder rechts „Generatoren ▾“). Später ändern: Schirm oder Sockel auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Wähle eine <b>Vorlage</b> (<b>Winterwald</b>, <b>Häuser</b>, <b>Sternenhimmel</b>) oder <b>Leer</b>.", "Wähle die <b>Teile</b>: <b>Schirm + Sockel</b>, <b>Nur Schirm</b> (z. B. für einen echten Holzklotz) oder <b>Nur Sockel</b>, dazu <b>Breite</b> und <b>Tiefe</b>.", "Stell beim Schirm <b>Höhe</b>, <b>Wand</b>, <b>Stufe</b> und <b>Rand</b> ein und wähle <b>Motiv innen</b> oder <b>Motiv außen</b>.", "Nimm unter <b>＋ Motiv dazu</b> eingebaute Motive oder lade mit <b>📂 SVG laden</b> eigene. Lege für jedes Motiv <b>Seite</b> (auch <b>alle 4</b> oder <b>rundum</b>), <b>Ebene</b> (1 hell … 3 dunkel, <b>Loch</b>), <b>Höhe</b> und Lage fest.", "Stell beim Sockel <b>Höhe</b>, <b>Kragen</b>, <b>Passung</b> und die Teelicht-Mulde ein, wähle <b>Glatt</b> oder Leisten und ggf. <b>Mit Kabel</b>.", "Klick auf <b>✓ Erstellen</b>."], "tipp": "Wo sich Motive überlappen, wird die Wand dicker und damit dunkler – so wirken Wald und Hirsch im Licht wie hintereinander. Den Schirm in Weiß drucken, den Sockel in Holz-Filament (am besten mit 0,6er Düse).", "run": "_mtlOpen()"},
  {"b": "Generatoren A–Z", "i": "🎁", "t": "Bild-Box", "k": "bild box klappbox scharnier dose motiv silhouette png deckel mehrfarbig geschenk print-in-place", "was": "Aus einem Bild (am besten PNG mit Transparenz) entsteht eine Klappbox in Form der Bild-Silhouette. Das Scharnier ist gleich mitgedruckt, das Motiv liegt mehrfarbig auf dem Deckel.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Bild-Box“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Mit <b>🖼️ Bild wählen</b> dein Motiv laden", "Unter Maße <b>Größe</b>, <b>Höhe (zu)</b> und <b>Wandstärke</b> einstellen", "Für das Motiv <b>Farben</b> (1–6), <b>Motiv-Höhe</b> und <b>Glättung</b> wählen, dazu <b>Wie Vorlage</b> oder <b>Gespiegelt</b>", "<b>Scharnier-Seite</b>, <b>Stift-Ø</b>, <b>Spiel</b> und den Verschluss (<b>Mit Lippe</b>/<b>Ohne</b>) festlegen", "Auf <b>✓ Erstellen</b> klicken"], "tipp": "Offen und flach ohne Stützen drucken. Ab 2 Farben schickt „An Slicer senden“ automatisch eine 3MF mit Farbzuordnung.", "run": "_openIbxModal()", "video": "bild-box"},
  {"b": "Generatoren A–Z", "i": "🖼️", "t": "Bilderrahmen", "k": "bilderrahmen rahmen foto bild aufhängen aufstellen standfuß stützbein schlüsselloch 10x15 a4", "was": "Du erzeugst einen Fotorahmen mit einer Tasche (Falz) hinten für Foto, Glas und Rückwand. Du kannst ihn an die Wand hängen oder aufstellen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Bilderrahmen“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Wähle das Bildformat (<b>9×13</b>, <b>10×15</b>, <b>13×18</b>, <b>15×20</b> oder <b>A4</b>, mit <b>↻ drehen</b>) oder trag Innen B/H ein.", "Stell den Rahmen über <b>Außen B</b>, <b>Außen H</b> und <b>Tiefe</b> ein.", "Stell den <b>Falz</b> mit <b>Einleger-Tiefe</b>, <b>Überlappung</b> und <b>Spiel</b> ein.", "Zum <b>Aufhängen</b> wählst du <b>Schlüsselloch</b>, zum <b>Aufstellen</b> <b>Standfuß</b> oder <b>Stützbein</b>.", "Klick auf <b>✓ Erstellen</b>."], "tipp": "Druck den Rahmen mit der Sichtseite nach unten, Stützen brauchst du nicht. Den Einleger legst du von hinten ein.", "run": "_bfrOpen()"},
  {"b": "Generatoren A–Z", "i": "✏️", "t": "Bild → SVG", "k": "svg vektor vektorisieren nachzeichnen trace bild foto jpg png kontur umriss silhouette laser", "was": "Hier zeichnest du ein Foto oder JPG als Konturen nach und bekommst eine maßhaltige SVG. Die kannst du lasern, an den Tortentopper hängen oder als flachen Körper in die Szene legen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Bild → SVG“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Lade ein Bild unter <b>📷 Bild wählen</b> oder füg es mit <b>📋 Aus Zwischenablage einfügen</b> (Strg+V) ein. Bei Bedarf wählst du einen <b>Bereich zum Nachzeichnen</b> aus.", "Wähle den Modus <b>Nachzeichnen</b>, <b>Außenrand</b> oder <b>Farbflächen</b> und klick auf <b>▶ Nachzeichnen</b>.", "Stell den <b>Schwellenwert</b> ein (gelb heißt erfasst), dazu <b>Glättung</b> und <b>Genauigkeit</b>.", "Leg die <b>Breite</b> in mm fest und klick dann auf <b>⬇ SVG speichern</b>, <b>➕ In die Szene</b> oder <b>🎂 In den Topper</b>."], "tipp": "Am saubersten werden Motive mit klaren Kanten und ruhigem Hintergrund.", "run": "_vecOpen()", "video": "svg-aufsetzen"},
  {"b": "Generatoren A–Z", "i": "🌸", "t": "Blume", "k": "blume blüte tulpe kelch glocke knospe schale deko vase gewinde blütenblätter", "was": "Du erzeugst eine Blüte als Deko-Form, wahlweise mit Gewindehals zum Aufschrauben.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Blume“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Wähle den <b>Blütentyp</b>: <b>Kelch</b>, <b>Glocke</b>, <b>Knospe</b> oder <b>Schale</b>.", "Forme die Blütenblätter mit <b>Anzahl</b>, <b>Tiefe</b>, <b>Spitze</b>, <b>Verdrehung</b>, <b>Zipfel</b> und <b>Glättung</b>.", "Stell unter Größe <b>Höhe</b>, <b>Durchmesser</b> und <b>Wandstärke</b> ein.", "Für ein Gewinde setzt du <b>Hals-Ø</b> über 0 und passt die <b>Hals-Höhe</b> an. Mit 0 bekommt die Blume kein Gewinde.", "Klick auf <b>✓ Blume erstellen</b>."], "run": "_openFlowerModal()"},
  {"b": "Generatoren A–Z", "i": "🌉", "t": "Brücke", "k": "brücke bruecke buckelbrücke auffahrt hochbahn viadukt fachwerk holzeisenbahn brio straße bögen kinder", "was": "Brücken für die Spielwelt: Buckelbrücke (beide Enden auf dem Boden, Mitte hoch), Auffahrt auf Hochbahn-Höhe, Hochbahn auf Bögen und eine flache Fachwerkbrücke. Wahlweise mit Holzeisenbahn-Gleis (Rillen und Zapfen) oder mit Straße und Geländer.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Brücke“, Thema „Spielwelt & Kinder“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Vorlage</b> die Brücke wählen.", "Bei <b>Für</b> <b>Holzeisenbahn</b> oder <b>Straße</b> wählen.", "<b>Länge</b> und <b>Höhe</b> einstellen (Hochbahn wie Brio: 76 mm), bei der Bahn auch die <b>Enden</b>.", "Farben wählen und <b>✓ Erstellen</b> klicken."], "tipp": "Die Bögen haben oben eine 45°-Spitze, deshalb druckt alles ohne Stützen. Für eine Hochbahn zwei Auffahrten und dazwischen Hochbahn-Stücke mit derselben Höhe bauen.", "run": "_kgOpen('bruecke')"},
  {"b": "Generatoren A–Z", "i": "🦖", "t": "Dinosaurier", "k": "dinosaurier dino riesenechse monster echse t-rex raptor spinosaurus brachiosaurus stegosaurus triceratops beweglich maul gelenke", "was": "Einer von zehn Dinosauriern, zum Beispiel T-Rex, Raptor oder Triceratops, dazu die Riesenechse (ein Kino-Monster mit Rückenzacken). Beine und Arme bewegen sich, das Maul lässt sich auf Wunsch öffnen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Dinosaurier“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Die <b>Art</b> und die <b>Länge</b> wählen", "Unter Körperbau <b>Hals</b>, <b>Schwanz</b> und <b>Beine</b> in % anpassen", "Gelenke auf <b>Stramm</b>/<b>Mittel</b>/<b>Locker</b> stellen, bei Bedarf <b>Maul beweglich</b> einschalten", "Unter Details <b>Zähne</b> und <b>Krallen</b> wählen", "Unter Ausgabe <b>Druckplatte</b> oder <b>Als Figur</b> wählen, dann <b>✓ Erstellen</b>"], "tipp": "Ohne Stützen drucken. Der Rumpf ist längs halbiert und wird zusammengeklebt, die Stifte richten die Hälften dabei aus.", "run": "_dnoOpen()"},
  {"b": "Generatoren A–Z", "i": "🌰", "t": "Eichel", "k": "eichel herbst hängeleuchte fenster teelicht led schuppen hut lichtpunkte schriftzug motiv herz öse", "was": "Du baust eine Hängeleuchte für das Fenster: eine Nuss mit Lichtpunkten, Motiv und Schriftzug und einen geschuppten Hut mit Öse. Das LED-Teelicht kommt in die Nuss, der Hut wird aufgeschraubt.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Eichel“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["<b>Nuss</b> (<b>Ø</b>, <b>Länge</b>, <b>Spitze</b>) und <b>Hut</b> (<b>Ø</b>, <b>Höhe</b>, <b>Schuppen</b>/<b>Glatt</b>, <b>🎲 Neu würfeln</b>) formen.", "Beim <b>Aufhänger</b> <b>Öse</b>, <b>Stiel</b> oder <b>Ohne</b> wählen und <b>Lichtpunkte</b> mit <b>Anzahl</b> und <b>Loch-Ø</b> festlegen.", "Optional ein <b>Motiv</b> (<b>Fenster</b>, <b>Vertieft</b>, <b>Erhaben</b>) und einen <b>Schriftzug</b> mit zwei Zeilen setzen, jeweils <b>Erhaben</b> oder <b>Vertieft</b>.", "Unter <b>Verbindung &amp; Licht</b> <b>Wandstärke</b>, Gewinde, <b>Spiel</b> und <b>Licht-Ø</b> einstellen, dann <b>✓ Erstellen</b>."], "tipp": "Ohne Stützen drucken: die Nuss kopfüber auf dem Gewindehals, den Hut auf seinem Rand. Bitte nur LED-Lichter verwenden, keine echte Kerze.", "run": "_eicOpen()"},
  {"b": "Generatoren A–Z", "i": "🪭", "t": "Faltkranz", "k": "faltkranz kranz facetten origami papier falten stumpenkerze teelicht vasenmodus kerze deko", "was": "Du bekommst einen Kranz in Facettenoptik wie aus gefaltetem Papier, mit Platz für ein Teelicht oder eine Stumpenkerze in der Mitte.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Faltkranz“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Wähle die <b>Kerze in der Mitte</b>: <b>Teelicht</b> oder <b>Stumpen 60</b>, <b>70</b> oder <b>80</b>, oder stell den <b>Innen-Ø</b> selbst ein.", "Stell <b>Außen-Ø</b>, <b>Höhe</b> und <b>Falten</b> ein.", "Forme ihn mit <b>Bauch</b>, <b>Fuß</b>, <b>Rundung</b> und <b>Drall</b>.", "Wähle unter <b>Druck</b> <b>Fertige Wand</b> (mit <b>Wand</b>, <b>Mit Boden</b> oder <b>Offener Ring</b>) oder <b>Vasenmodus</b>.", "Klick auf <b>✓ Erstellen</b>."], "tipp": "Bei Vasenmodus schaltest du im Slicer Vasenmodus/Spirale mit 3–4 Bodenschichten ein. Sonst druckst du normal ohne Stützen.", "run": "_fkzOpen()"},
  {"b": "Generatoren A–Z", "i": "🚗", "t": "Fahrzeug", "k": "fahrzeug auto polizei feuerwehr bus laster lkw traktor rennauto spielzeugauto räder kinder", "was": "Spielzeugautos mit drehenden Rädern: Auto, Polizei, Feuerwehr, Bus, Laster, Traktor und Rennauto. Sie passen auf die Straßenplatten.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Fahrzeug“, Thema „Spielwelt & Kinder“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Vorlage</b> ein Fahrzeug wählen.", "<b>Länge</b> und Farben einstellen und <b>✓ Erstellen</b> klicken.", "Dazu kommen 4 Räder und 4 Steckachsen als eigene Teile.", "Nach dem Druck: Achse durch das Rad in das Loch an der Seite drücken, bis sie stramm sitzt."], "tipp": "Druckt ohne Stützen. Sitzt eine Achse zu locker, einen Tropfen Kleber ins Loch geben. Sitzt sie zu stramm, das Loch kurz mit einem 3-mm-Bohrer aufreiben.", "run": "_kgOpen('fahrzeug')"},
  {"b": "Generatoren A–Z", "i": "🧸", "t": "Figur-Baukasten", "k": "figur baukasten mensch tier fantasie drache fee hund katze ki skulptur base", "was": "Hier baust du Menschen, Tiere und Fantasiewesen aus einer Vorlage und veränderst sie frei. Heraus kommt ein einziger wasserdichter Körper, auf Wunsch mit Base.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Figur-Baukasten“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Eine <b>Vorlage</b> wählen, zum Beispiel <b>Mensch</b>, <b>Katze</b> oder <b>Drache</b>", "Unter Körper <b>Körperbau</b>, <b>Pose</b>, <b>Höhe</b>, <b>Kopf</b>, <b>Fülle</b> und mehr einstellen", "Unter Merkmale Gesicht, Augen, Ohren, Kopfputz, Hörner und Flügel wählen", "Unter Druck <b>Base</b> und <b>Detail</b> wählen, dann <b>✓ Erstellen</b>, oder für Unikate <b>✨ KI-Figur aus Beschreibung</b> nutzen"], "tipp": "Lose Splitter werden verworfen, die Figur ist ein wasserdichter Körper. Den Feinschliff machst du danach mit 🖌️ Modellieren.", "run": "_fgbOpen()"},
  {"b": "Generatoren A–Z", "i": "🐉", "t": "Flexi-Drache", "k": "flexi drache beweglich gelenke print-in-place schlüsselanhänger öse zwei farben glieder spielzeug", "was": "Ein beweglicher Drache, der in einem Stück gedruckt wird, ganz ohne Zusammenbauen. Auch als kleiner Schlüsselanhänger oder aus deinem eigenen Bild bzw. SVG.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Flexi-Drache“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter Motiv <b>🐉 Drache</b> oder <b>🖼️ Eigenes Motiv</b> wählen, als Vorlage <b>🐉 Drache</b> oder <b>🔑 Schlüsselanhänger</b>", "<b>Länge</b>, <b>Dicke</b> und Anzahl der <b>Glieder</b> einstellen", "Aussehen wählen: Körperform, Zacken, Flügel, Beine, Schwanz", "Unter Farben <b>Akzente</b>, <b>Streifen</b> oder <b>Einfarbig</b> wählen, bei Bedarf eine <b>Öse am Schwanz</b>/<b>Öse am Kopf</b> anbringen", "<b>Spiel</b> und <b>Beweglichkeit</b> setzen, dann <b>✓ Erstellen</b>"], "tipp": "Flach und ohne Stützen drucken, danach jedes Gelenk einmal vorsichtig biegen. Spiel 0,4 mm passt für die meisten Drucker, bei Klemmen 0,5 mm nehmen.", "run": "_fdrOpen()"},
  {"b": "Generatoren A–Z", "i": "✈️", "t": "Flugzeug", "k": "flugzeug flieger jet jumbo propeller düsenjäger segelflugzeug segler ständer kinder spielzeug luft", "was": "Ein Spielzeug-Flugzeug: Passagierjet, Jumbo, Propellerflugzeug, Düsenjäger oder Segelflieger. Unten ist alles flach, darum druckt es ohne Stützen. Auf Wunsch gibt es einen passenden Ständer dazu, der das Flugzeug im Steigflug in die Luft hält.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Flugzeug“, Thema „Spielwelt & Kinder“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Vorlage</b> ein Flugzeug wählen, z. B. <b>✈️ Passagierjet</b> oder <b>🛩️ Propeller</b>.", "<b>Länge</b>, <b>Spannweite</b> und <b>Pfeilung</b> einstellen, dazu <b>Triebwerke</b>, <b>Propeller</b>, <b>Seitenleitwerk</b> und <b>Fenster</b>.", "Bei <b>Ständer</b> „Mit Ständer“ lassen und <b>Ständer-Höhe</b> und <b>Steigflug</b> wählen.", "<b>Mehrfarbig</b> oder <b>Einfarbig</b> wählen, die Farben aussuchen und <b>✓ Erstellen</b> klicken."], "tipp": "Das Flugzeug und den Ständer getrennt drucken. Der Ständer steckt mit seinem Zapfen in das Loch im Bauch.", "run": "_kgOpen('flugzeug')"},
  {"b": "Generatoren A–Z", "i": "🤳", "t": "Foto-Requisite", "k": "foto requisite polaroid rahmen photobooth party hochzeit schriftzug herz selfie fotobox", "was": "Du baust einen Polaroid-Rahmen mit geschwungenem Schriftzug zum Hochhalten, für Fotobox und Party.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Foto-Requisite“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Gib den <b>Schriftzug</b> ein, wähl die Schrift und auf Wunsch <b>An Rahmenbreite anpassen</b>.", "Stell <b>Bogen</b> und <b>Eintauchen</b> des Schriftzugs ein.", "Leg den <b>Rahmen</b> mit <b>Breite</b>, <b>Höhe</b>, <b>Rand</b>, <b>Bodenleiste</b> und <b>Stärke</b> fest.", "Setz unter <b>Deko</b> optional ein <b>Herz auf der Bodenleiste</b> und stell die <b>Herz-Größe</b> ein.", "Klick auf <b>✓ Erstellen</b>."], "tipp": "Druck flach liegend ohne Stützen. Schriftzug und Herz sind eigene Teile, die du in einer Kontrastfarbe drucken kannst (mit AMS/Mehrfarbdruck in einem Durchgang).", "run": "_fppOpen()"},
  {"b": "Generatoren A–Z", "i": "🚿", "t": "Gardena-Anschluss", "k": "gardena schlauch kupplung hahn wasserhahn klick stecker buchse tülle gewinde garten adapter reparator", "was": "Du druckst passende Teile für das Gardena-Klicksystem, etwa Hahnverbinder, Schlauchstück, Reparator oder Kupplung. Beide Enden kannst du frei kombinieren.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Gardena-Anschluss“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Bei <b>Grundmodelle</b> eine Vorlage anklicken, z. B. <b>Hahnverbinder</b>, <b>Schlauchstück</b>, <b>Reparator</b>, <b>Kupplung 19→13</b> oder <b>Hahnstück 1:1</b>.", "Für <b>Ende A</b> und <b>Ende B</b> die Art wählen (<b>Klick-Stecker</b>, <b>Klick-Buchse</b>, <b>Schlauchtülle</b>, <b>Außengewinde</b>, <b>Innengewinde</b>).", "Dazu <b>Gewinde</b> (G½\", G¾\", G1\"), <b>Schlauch-Ø</b> und <b>Länge</b> einstellen.", "Unter <b>Mittelteil &amp; Toleranzen</b> <b>Gewinde-Spiel</b> und <b>Klick-Toleranz</b> anpassen, dann <b>✓ Erstellen</b>."], "tipp": "Für die Klick-Buchse einen O-Ring einlegen und am besten mit PETG oder TPU drucken. Die Klick-Toleranz am fertigen Druck nachstellen.", "run": "_openGardenaModal()"},
  {"b": "Generatoren A–Z", "i": "🕯️", "t": "Geflochtener Kranz", "k": "adventskranz kranz geflochten zopf strick kordel kerzen teelicht stumpen advent weihnachten", "was": "Du erzeugst einen Adventskranz in Strickoptik aus drei geflochtenen Strängen. Die Kerzen sitzen in Mulden im Kranz, in der Mitte oder an beiden Stellen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Geflochtener Kranz“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Stell beim <b>Kranz</b> <b>Außen-Ø</b>, <b>Strang-Ø</b>, <b>Weite</b>, <b>Wölbung</b> und <b>Flechtung</b> ein.", "Wähle die <b>Oberfläche</b> <b>Strick</b>, <b>Kordel</b> oder <b>Glatt</b>, dazu <b>Masche</b> und <b>Tiefe</b>.", "Wähle die Kerzen-Position (<b>Im Kranz</b>, <b>In der Mitte</b>, <b>Beides</b> oder <b>Ohne</b>) und den Kerzentyp <b>Stabkerze</b>, <b>Teelicht</b> oder <b>Stumpen</b>.", "Lege <b>Anzahl</b> und Verteilung fest (<b>Ringsum</b> oder <b>Als Gruppe</b>), dazu <b>Mulden-Ø</b>, <b>Tiefe</b> und <b>Lage</b>.", "Klick auf <b>✓ Erstellen</b>."], "tipp": "Druck den Kranz flach ohne Stützen. Ist er größer als 256 mm, teilst du ihn mit ✂ Schneiden. Echte Kerzen nur mit Kerzenteller, sicherer sind LED-Kerzen.", "run": "_krzOpen()"},
  {"b": "Generatoren A–Z", "i": "📦", "t": "Gehäuse / Box", "k": "gehäuse box kasten deckel unterteil schraubdome m3 m4 wandstärke elektronik lippe", "was": "Erzeugt eine parametrische Box als oben offenes Unterteil oder als passenden Deckel mit Lippe – z. B. als Gehäuse für Elektronik.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Gehäuse / Box“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Teil</b> <b>Unterteil</b> oder <b>Deckel</b> wählen.", "<b>Maße (außen)</b>: <b>Breite</b>, <b>Tiefe</b>, <b>Höhe</b> und <b>Wandstärke</b> einstellen.", "<b>Schraubdome</b>: <b>Mit Domen</b> oder <b>Ohne</b>, dazu Größe <b>M3</b> oder <b>M4</b>.", "<b>✓ Erstellen</b>; für den Deckel das Fenster mit gleichen Maßen erneut öffnen."], "tipp": "Unterteil und Deckel sind zwei getrennte Teile; der Deckel hat eine umlaufende Lippe, die ins Unterteil passt.", "run": "_openEncModal()"},
  {"b": "Generatoren A–Z", "i": "💶", "t": "Geldgeschenk (Laser)", "k": "geldgeschenk laser reisekasse weltkarte holz sperrholz svg gravur schneiden band zubinden geldschein", "was": "Du bekommst zwei Holzplatten zum Lasern, zwischen die Geldscheine kommen. Vorne werden der Spruch graviert und ein Motiv-Fenster (z. B. eine Weltkarte) ausgeschnitten, durch das man das Geld sieht.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Geldgeschenk (Laser)“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Wähle unter <b>Spruch</b> eine Vorlage oder schreib einen eigenen Text, dann Schrift und <b>Schrifthöhe</b>.", "Wähle das <b>Motiv-Fenster</b> und lege fest, ob es <b>Ausschneiden</b> oder <b>Gravieren</b> soll, dazu Größe % und Text oben/unten.", "Wähle unter <b>Platte</b> ein DIN-Format oder <b>Eigene Maße</b>, jeweils <b>Querformat</b> oder <b>Hochformat</b>.", "Wähle unter <b>Zubinden</b> <b>Löcher</b> oder <b>Schlitze</b> und ob das Band links + rechts oder oben + unten läuft.", "Speichere mit <b>⬇ Vorderseite</b>, <b>⬇ Rückseite</b> oder <b>⬇ Beide (SVG)</b>."], "tipp": "Im SVG bedeutet schwarz gefüllt gravieren und rot schneiden. Graviere zuerst und schneide danach.", "run": "_ggpOpen()"},
  {"b": "Generatoren A–Z", "i": "⭐", "t": "Belohnungstafel (Laser)", "k": "belohnungstafel belohnung wochenplan kind kinder aufgaben sterne magnet magnete marker holz laser svg gravur", "was": "Du bekommst einen Wochenplan aus Holz zum Lasern: Überschrift, eigene Aufgaben mit kindlichen Symbolen, Spalten für die Wochentage und unten Ziel und Belohnung. Dazu Marker (Stern, Herz, Smiley, Sonne), die mit Magneten auf den Feldern halten.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Belohnungstafel (Laser)“ (oder rechts „Generatoren ▾“).", "s": ["Schreib die <b>Überschrift</b>, z. B. „Theos Belohnungstafel“, und wähle Schrift und Deko-Symbol.", "Trag unter <b>Aufgaben</b> die Aufgaben ein. Das Symbol wird passend zum Text gewählt, du kannst es aber auch selbst aussuchen.", "Wähle <b>Mo – So</b> oder <b>Mo – Fr</b>. Trag unten im <b>Namenskärtchen</b> Name, Sterne-Ziel und Belohnung ein – für bis zu 3 Kinder, jedes bekommt eigene Marker (Stern, Herz, Sonne).", "Lege unter <b>Magnete</b> fest: Blech hinter der Tafel oder Rückplatte mit einem Loch je Feld, dazu Magnetgröße.", "Wähle Anzahl, Motiv und Form der <b>Marker</b> und speichere mit <b>⬇ Tafel</b>, <b>⬇ Marker</b> oder <b>⬇ Alles (SVG)</b>."], "tipp": "Im SVG bedeutet schwarz gefüllt gravieren und rot schneiden. Mit „Holzring mit Loch“ verschwindet der Magnet in einer zweiten Lage hinter dem Marker.", "run": "_belOpen()"},
  {"b": "Generatoren A–Z", "i": "🍷", "t": "Glas-Marker", "k": "glasmarker glas marker clip party weinglas flasche glasrand namen motive tiere erkennung", "was": "Du erzeugst Party-Clips mit Motiven, Namen, Buchstaben oder Zahlen. Damit erkennt jeder Gast sein Weinglas, seine Flasche oder sein Glas wieder.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Glas-Marker“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Wähle die <b>Halterung</b>: <b>Weinglas</b> (<b>Stiel-Ø</b>), <b>Flasche</b> (<b>Hals-Ø</b>, <b>Klemmung</b>) oder <b>Glasrand</b>.", "Wähle unter <b>Kennung</b> die <b>Anzahl</b> und einen Satz, z. B. Tiere, <b>Eigene Namen</b> oder Zahlen.", "Stell die <b>Ausführung</b> <b>Durchbrochen</b> oder <b>Erhaben</b> ein, dazu <b>Motivgröße</b>.", "Pass unter <b>Druck &amp; Technik</b> <b>Wandstärke</b>, <b>Bauhöhe</b> und <b>Schildhöhe</b> an.", "Klick auf <b>✓ Erstellen</b>."], "tipp": "Druck die Marker flach ohne Stützen. Für den Glasrand federn PETG oder TPU besser als PLA.", "run": "_gmkOpen()"},
  {"b": "Generatoren A–Z", "i": "🪛", "t": "Halterplatte", "k": "halterplatte halter bohrer inbus tortentopper stifte werkzeug satz aufnahme sortierung beschriftung", "was": "Erzeugt eine Platte mit Aufnahmen für Bohrer, Inbus-Schlüssel, Stifte oder Tortentopper – auf Wunsch als Satz mit aufsteigenden Größen und Beschriftung.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Halterplatte“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["<b>Form der Aufnahme</b> wählen (<b>Rund</b>, <b>Quadrat</b>, <b>Rechteck</b>, <b>Sechskant</b>) und Größe einstellen.", "Für Sätze <b>Größen aufsteigend (Satz)</b> mit <b>Schrittweite</b> nutzen; <b>Zugabe</b> für die Passung wählen.", "<b>Aufnahmen je Reihe</b>, <b>Reihen</b> sowie <b>Taschentiefe</b> oder <b>Durchgehende Löcher</b> festlegen.", "Außenmaß, <b>Material</b> (<b>Massiv</b>/<b>Gitter (spart)</b>) und <b>Größen beschriften</b> einstellen, dann <b>✓ Erstellen</b>."], "tipp": "<b>Zugabe</b> 0,3 mm sitzt saugend, 0,5–1 mm locker; die <b>Einführfase</b> hilft beim Einstecken.", "run": "_hpOpen()"},
  {"b": "Generatoren A–Z", "i": "🏠", "t": "Häuser", "k": "haus häuser stadthaus hochhaus laden geschäft feuerwache bahnhof bahnsteig stadt spielstadt fenster schild kinder", "was": "Häuser für die Spielstadt: Haus mit Satteldach, Stadthaus, Hochhaus, Laden mit gestreifter Markise, Feuerwache mit Toren und Turm und Bahnhof mit Bahnsteig in Schienenhöhe. Fenster und Türen sind eingelassen und farbig. Auf Wunsch kommt ein Schild mit eigenem Text dazu.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Häuser“, Thema „Spielwelt & Kinder“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Vorlage</b> ein Gebäude wählen.", "<b>Breite</b>, <b>Tiefe</b>, <b>Stockwerke</b> und <b>Stockwerk-Höhe</b> einstellen.", "<b>Dach</b> (<b>Satteldach</b> oder <b>Flachdach</b>) und <b>Dachneigung</b> wählen und bei <b>Schild</b> einen Text eintippen.", "Farben wählen und <b>✓ Erstellen</b> klicken."], "tipp": "Druckt ohne Stützen. Mit wenig Füllung (z. B. 10 %) geht es schnell. Vor den Bahnhof passt ein Holzeisenbahn-Gleis.", "run": "_kgOpen('haus')"},
  {"b": "Generatoren A–Z", "i": "🗺️", "t": "Karte → 3D", "k": "karte map stadt stadtmodell openstreetmap osm gebäude relief gelände straßen wasser satellit mehrfarbig", "was": "Aus einem Kartenausschnitt von OpenStreetMap entsteht ein druckbares Stadtmodell. Gebäude, Grünflächen, Wasser und Straßen sitzen dabei auf einem Sockel.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Karte → 3D“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Such den Ort mit <b>🔍 Suchen</b>. Wähle als Ansicht <b>Karte</b> oder <b>Satellit</b> und als <b>Form</b> Quadrat, Rechteck, Kreis oder Sechseck.", "Stell <b>Ausschnitt</b> in m, <b>Modellbreite</b>, <b>Max. Höhe</b> und <b>Grundplatte</b> ein.", "Wenn du echtes Gelände willst, schalte das <b>Höhenrelief</b> ein und stell die <b>Überhöhung</b> ein.", "Wähle den <b>Inhalt</b> (Grünflächen, Wasser, Straßen) und die <b>Farben</b>. Dazu kannst du einen <b>Rahmen</b> aktivieren und <b>Teile getrennt einfügen</b>.", "Klick auf <b>✓ Modell erzeugen</b>."], "tipp": "Ein kleiner Ausschnitt wird schneller erzeugt und hat weniger Objekte. Für den Mehrfarbdruck fügst du die Teile getrennt ein.", "run": "_openMapModal()"},
  {"b": "Generatoren A–Z", "i": "🍪", "t": "Keksausstecher", "k": "keksausstecher ausstecher plätzchen backen bild silhouette schneide form kekse", "was": "Aus einem Bild mit klarer Silhouette entsteht ein Keksausstecher mit dünner Schneide und Griffrand. Es zählt nur der Außenumriss.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Keksausstecher“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Mit <b>🖼️ Bild wählen (Silhouette)</b> das Motiv laden", "Unter Maße <b>Größe</b> und <b>Höhe</b> einstellen", "<b>Schneide</b>, <b>Rand</b>, <b>Rand-Höhe</b> und <b>Glättung</b> anpassen", "Auf <b>✓ Erzeugen</b> klicken"], "tipp": "Mit dem Rand nach unten drucken, die dünne Schneide zeigt nach oben.", "run": "_ckOpen()"},
  {"b": "Generatoren A–Z", "i": "✨", "t": "KI-Modell", "k": "ki ai künstliche intelligenz generieren text prompt bild foto 3d modell flux hunyuan", "was": "Die KI erzeugt dir ein 3D-Modell aus einer Textbeschreibung oder aus einem Bild. Das ist kostenlos, braucht keinen API-Schlüssel und läuft über Hugging Face.", "wo": "Oben Reiter <b>GENERATOREN</b> → „KI-Modell“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Öffne den Reiter <b>📝 Text</b> und beschreib das Modell im Eingabefeld, zum Beispiel „mechanical gear“.", "Oder öffne den Reiter <b>🖼 Bild</b> und leg ein Bild ab.", "Klick auf <b>✨ Generieren</b> und warte etwa eine Minute. Der Fortschrittsbalken zeigt dir den Stand."], "run": "kiTogglePanel()"},
  {"b": "Generatoren A–Z", "i": "🧱", "t": "Klemmbaustein-Look", "k": "lego klemmbaustein noppen bausteine raster voxel bausatz steine stückliste bauanleitung blockig", "was": "Dein ausgewähltes Modell wird auf das Noppenraster gelegt. Heraus kommt entweder ein einziges Druckteil im Klemmbaustein-Look oder ein echter Bausatz aus einzelnen Steinen mit Stückliste und Bauanleitung.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Klemmbaustein-Look“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Wähl das Modell aus und entscheide dich für <b>Ein Stück</b> oder <b>Echter Bausatz</b>.", "Wähle die Rasterhöhe <b>Stein 9,6 mm</b> oder <b>Platte 3,2 mm</b> und stell <b>Breite</b> (in Noppen) und <b>Füllgrad</b> ein.", "Leg die Steindetails fest: <b>Noppen oben</b>, <b>Aufnahme unten</b>, <b>Spiel</b> und <b>Fugen zwischen den Steinen</b>.", "Beim Bausatz kommen <b>Längster Stein</b>, <b>Fugen versetzen</b> und die Ausgabe <b>Zusammengebaut</b> oder <b>Druckplatte</b> dazu. Klick dann auf <b>✓ Erzeugen</b>."], "tipp": "Bei filigranen Modellen erhöhst du zuerst die Breite oder stellst auf „Platte 3,2 mm“ um. Für die meisten FDM-Drucker passen 0,2 mm Spiel.", "run": "_lgoOpen()"},
  {"b": "Generatoren A–Z", "i": "🎃", "t": "Kürbis", "k": "kürbis halloween herbst deko dose naschschale teelicht deckel gesicht lichtpunkte schriftzug", "was": "Du gestaltest einen Halloween- oder Deko-Kürbis, entweder massiv, hohl mit Deckel für ein LED-Teelicht oder als offene Schale.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Kürbis“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Wähle eine <b>Vorlage</b>: <b>🎃 Halloween</b>, <b>🍂 Deko-Dose</b> oder <b>🥣 Naschschale</b>.", "Stell <b>Ø</b>, <b>Höhe</b>, <b>Rippen</b>, <b>Rippen-Form</b> und <b>Bauchig</b> ein. Mit <b>🎲 Neue Variante würfeln</b> bekommst du eine neue Form.", "Wähle den Stiel (<b>Strunk</b> oder <b>Glatt</b>) und ein <b>Gesicht</b>, dazu optional <b>Lichtpunkte</b> und einen <b>Schriftzug</b>.", "Wähle unter <b>Druck &amp; Technik</b> <b>Massiv</b>, <b>Hohl + Deckel</b> oder <b>Schale</b>, dazu den Deckel <b>Deckel klein</b> oder <b>Schulter (wellig)</b> und das <b>Spiel</b>.", "Klick auf <b>✓ Erstellen</b>."], "tipp": "Druck Körper und Deckel einzeln und aufrecht. Benutz nur ein LED-Teelicht, keine echte Kerze. Einen echten, gescannten Kürbis schnitzt du über „🎃 Gewählten Kürbis schnitzen…“ ganz oben im Fenster (siehe „Kürbis schnitzen (eigener Scan)“).", "run": "_openKbsModal()"},
  {"b": "Generatoren A–Z", "i": "💡", "t": "Lampe", "k": "lampe lampenschirm poplamp pushlampe led puck bambu lithophane foto rillen twist facetten nachttisch", "was": "Du baust einen Lampenschirm im Pop-Lamp-Stil mit Tasche für die Bambu-LED-Scheibe. Alternativ entsteht eine Push-Lampe aus Basis und Schirm, die du zum Ein- und Ausschalten drückst.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Lampe“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Eine <b>Form</b> wählen (<b>Gerade</b>, <b>Konisch</b>, <b>Bauchig</b>), dann <b>Höhe</b>, <b>Grund-Ø</b>, <b>Top-Ø</b>, <b>Bauchigkeit</b> und <b>Wandstärke</b> einstellen.", "Ein <b>Muster</b> wählen: <b>Glatt</b>, <b>Rillen</b>, <b>Twist</b>, <b>Facetten</b> oder <b>🖼️ Foto</b> (Lithophane über <b>📷 Motiv wählen</b>).", "Bei <b>Aufnahme</b> <b>Standalone (LED)</b> oder <b>Push-Basis (Puck)</b> wählen und <b>LED-Ø</b>, <b>Puck-Ø</b>, <b>Hubweg</b> und <b>Spiel</b> anpassen.", "Optional <b>Oben geschlossen (Kuppel)</b> und <b>Kabel-Aussparung unten</b> anhaken, dann <b>✓ Erstellen</b>."], "tipp": "Den Schirm kopfüber drucken, mit der geschlossenen Seite aufs Bett, dann brauchst du keine Stützen. Die Push-Lampe besteht aus Basis und Schirm, die du getrennt druckst.", "run": "_openLampModal()"},
  {"b": "Generatoren A–Z", "i": "🪵", "t": "Laser-Box (Zinken)", "k": "laser lasercut box kiste fingerzinken zinken sperrholz acryl kerf steckbox svg lightburn xtool", "was": "Du bekommst eine Steckkiste mit Fingerzinken für den Lasercutter, aus Sperrholz oder Acryl. Die Teile werden nur zusammengesteckt und halten ohne Schrauben.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Laser-Box (Zinken)“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Stell <b>Breite B</b>, <b>Tiefe T</b> und <b>Höhe H</b> ein. Das sind die Außenmaße, jeweils 20 bis 300 mm.", "Wähle das Material (3/4/5 mm Sperrholz oder 3 mm Acryl) oder gib eine eigene <b>Materialstärke</b> ein.", "Stell den <b>Kerf-Ausgleich</b> für einen strammen Pressfit ein und lass die <b>Zinkenbreite</b> auf <b>Auto</b> oder stell sie <b>Manuell</b> ein.", "Wähle den Kistentyp <b>Geschlossen</b> oder <b>Oben offen</b>.", "Lade die Teile mit <b>⬇ SVG-Export</b> herunter oder leg die Kiste mit <b>✓ In Szene</b> in die Szene."], "tipp": "Im SVG liegen die Schnitte auf der Ebene „cut“ als rote Haarlinie und die Beschriftungen auf „engrave“, passend für LightBurn und xTool. Ist das Material zu dick für deine Maße, sperrt der Generator den Export.", "run": "_openLBModal()"},
  {"b": "Generatoren A–Z", "i": "🏮", "t": "Laterne", "k": "laterne windlicht leuchte lichtmuster durchbrochen bügel henkel streifen gitter waben rauten tonne turm", "was": "Du baust eine Laterne mit durchbrochenem Lichtmuster in der Wand und einem Tragebügel.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Laterne“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Eine <b>Körperform</b> wählen: <b>Zylinder</b>, <b>Tonne</b>, <b>Laterne</b> oder <b>Turm</b>.", "Ein <b>Muster</b> wählen (<b>Streifen</b>, <b>Gitter</b>, <b>Rauten</b>, <b>Punkte</b>, <b>Waben</b>, <b>Bogen</b>) und <b>Dichte</b> sowie <b>Öffnung</b> anpassen.", "Bei <b>Größe</b> <b>Höhe</b>, <b>Durchmesser</b> und <b>Wandstärke</b> festlegen.", "Den Bügel über <b>Bügel-Höhe</b> und <b>Bügel-Stärke</b> einstellen, dann <b>✓ Laterne erstellen</b>."], "tipp": "Der Bügel wird als eigenes, flaches Teil neben die Laterne aufs Druckbett gelegt.", "run": "_openLanternModal()"},
  {"b": "Generatoren A–Z", "i": "⛰️", "t": "Landschaft", "k": "landschaft platte hügel berg tunnel teich see fluss wald acker gelände spielteppich holzeisenbahn kinder", "was": "Landschaftsplatten für die Spielwelt: Hügel, Berg mit Tunnel für die Holzeisenbahn, Teich, Fluss, Wald mit Bäumen und Acker. Sie haben dieselbe Größe und dieselben Puzzle-Kanten wie die Straßenplatten, die Ränder laufen flach aus.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Landschaft“, Thema „Spielwelt & Kinder“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Vorlage</b> die Platte wählen.", "<b>Plattengröße</b> (wie die Straßen), <b>Höhe</b> und <b>Variante</b> einstellen, beim Wald die Zahl der <b>Bäume</b>, beim Fluss die <b>Fluss-Breite</b>.", "Farben wählen und <b>✓ Erstellen</b> klicken."], "tipp": "Druckt ohne Stützen. Der Berg ist groß, darum mit wenig Füllung (10 %) drucken. Mehrere Fluss-Platten hintereinander ergeben einen langen Fluss.", "run": "_kgOpen('landschaft')"},
  {"b": "Generatoren A–Z", "i": "🥫", "t": "Dose mit Motiv", "k": "dose motiv deckel geschlossen name text svg rundherum vase becher stifthalter gefäß eckig rundung etikett gravur erhaben durchbruch windlicht", "was": "Du baust eine eckige Dose mit runden Kanten. Ein Name oder ein eigenes SVG läuft wie ein Etikett um die Rundungen herum und wird vertieft, erhaben oder als Durchbruch eingearbeitet.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Dose mit Motiv“ (oder rechts „Generatoren ▾“).", "s": ["Unter <b>Dose</b> <b>Breite</b>, <b>Tiefe</b>, <b>Höhe</b>, <b>Eckradius</b>, <b>Oben</b> (konisch), <b>Wand</b> und <b>Boden</b> einstellen.", "Beim <b>Motiv</b> <b>🔤 Text</b> mit Schrift wählen oder <b>🖼️ Eigenes SVG</b> mit <b>📂 SVG-Datei wählen</b> laden.", "Oben <b>Oben offen</b>, <b>+ Deckel</b> (zweites Teil mit Steckrand, dazu <b>Decke</b>, <b>Steckrand</b> und <b>Spiel</b>) oder <b>Oben zu</b> (geschlossen, hohl) wählen.", "<b>Motivhöhe</b> und <b>Lage</b> (Höhe auf der Dose) festlegen und <b>1× vorne</b>, <b>2× vorn+hinten</b> oder <b>4× rundum</b> wählen.", "<b>Vertieft</b>, <b>Erhaben</b> oder <b>Durchbruch</b> wählen, dazu die <b>Gravurtiefe</b> bzw. <b>Höhe (erhaben)</b>, dann <b>✓ Erstellen</b>."], "tipp": "Ist das Motiv breiter als die ebene Seite, läuft es um die runden Kanten bis auf die Nachbarseite. Passen mehrere Motive nicht nebeneinander, verkleinert V3D CAD sie automatisch. Die Gravur sollte deutlich flacher als die Wand sein. Den Deckel mit der Platte nach unten drucken; bei <b>Oben zu</b> muss die Decke frei überbrücken – über ca. 45 mm Innenbreite im Slicer Stützen einschalten.", "run": "_mdsOpen()"},
  {"b": "Generatoren A–Z", "i": "🐆", "t": "Leo-Windlicht", "k": "windlicht leo leopard muster tupfen teelicht led schrauben gewinde sockel relief deko licht", "was": "Du baust ein Windlicht aus einem kegeligen Oberteil mit Leoparden-Rosetten und einem bauchigen Sockel, die du zusammenschraubst. Im Sockel sitzt ein Podest mit Mulde für ein LED-Teelicht.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Leo-Windlicht“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Oberteil</b> <b>Ø unten</b>, <b>Ø oben</b>, <b>Höhe</b> und <b>Wand</b> einstellen.", "Beim <b>Muster</b> <b>🐆 Leo</b>, <b>⚪ Tupfen</b> oder <b>Glatt</b> wählen, dazu <b>Fleckgröße</b>, <b>Relief-Höhe</b> und <b>Relief außen</b> oder <b>Relief innen</b> (<b>🎲 Neues Muster würfeln</b>).", "Unter <b>Sockel</b> <b>Höhe</b>, <b>Bauch</b>, <b>Fuß</b>, <b>Wand</b> und <b>Überhang max</b> festlegen.", "Bei <b>Licht &amp; Gewinde</b> <b>Teelicht-Ø</b>, <b>Teelicht-Höhe</b>, <b>Steigung</b> und <b>Spiel</b> anpassen, dann <b>✓ Erstellen</b>."], "tipp": "Beide Teile werden aufrecht und ohne Stützen gedruckt, das Oberteil in Hell und den Sockel gern in Dunkel. Mit 1–1,4 mm Wand aus weißem PLA scheint das Licht schön durch.", "run": "_lwlOpen()"},
  {"b": "Generatoren A–Z", "i": "🔤", "t": "Leucht-Buchstaben", "k": "leuchtbuchstaben buchstaben zahlen name licht lichterkette led streifen diffusor schild geburtstag rückwand", "was": "Du baust hohle Buchstaben und Zahlen wie bei einer Leuchtreklame, etwa „18“ oder einen Namen. Hinten sind sie offen für eine Mini-Lichterkette oder einen LED-Streifen, vorne kann eine dünne Diffusor-Haut sitzen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Leucht-Buchstaben“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Den <b>Text</b> eingeben und eine <b>Schrift</b> wählen (<b>🔎 Katalog</b> oder <b>＋ Eigene Datei</b>).", "Bei <b>Maße</b> <b>Höhe</b>, <b>Tiefe</b>, <b>Wandstärke</b> und <b>Laufweite</b> einstellen.", "Für die <b>Vorderseite</b> <b>Diffusor</b> oder <b>Offen</b> wählen, optional <b>Kabel-Kerbe unten</b> und <b>Rückwand einlegen</b> mit <b>Streifen-Kanal</b>.", "<b>Bauart</b> <b>Getrennt</b>/<b>Verbunden</b> und optional ein <b>Bord zum Hinstellen</b> wählen, dann <b>✓ Erstellen</b>."], "tipp": "In der Druck-Lage liegen die Zeichen mit dem Gesicht nach unten und drucken ohne Stützen. Weißes oder naturfarbenes Filament leuchtet am schönsten durch.", "run": "_lbsOpen()"},
  {"b": "Generatoren A–Z", "i": "🎨", "t": "Chroma (Filament-Bild)", "k": "chroma hueforge bild foto gemälde farbschichten filament farbwechsel eine düse ohne ams td transmission relief bild drucken", "was": "Aus einem Foto wird eine flache Platte, die als Farbbild gedruckt wird – mit einer Düse und ohne Reinigungsturm. Die Höhe je Bildpunkt bestimmt, wie viele dünne Schichten übereinander liegen; die Filamente wechseln nur an festen Höhen (dunkel unten, hell oben), dünne Schichten scheinen durch und mischen sich zu Verläufen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Chroma (Filament-Bild)“ (oder rechts „Generatoren ▾“).", "s": ["Lade unter <b>🖼️ Bild wählen</b> ein Foto oder PNG. V3D CAD schlägt 4 Filamentfarben aus dem Bild vor.", "Trag deine echten Filamente ein (Farbe und <b>TD</b> – die Dicke, ab der das Filament deckt; Wert aus der HueForge-Liste oder vom Hersteller). Mit ▼▲ die Reihenfolge ändern, dunkel gehört nach unten.", "Prüf links die <b>Druck-Vorschau</b>; <b>Farbtreue</b>, <b>Max. Höhe</b> und <b>Glättung</b> verbessern das Ergebnis.", "Wähl <b>AMS (automatisch)</b> oder <b>Von Hand (Pause)</b> und klick auf <b>✓ Erstellen</b>.", "Als <b>3MF</b> exportieren: Mit AMS stehen die Wechsel als Höhenbereiche schon drin. Von Hand: im Slicer an den Schichten aus dem Plan eine Pause setzen."], "tipp": "Die Platte nach dem Erstellen nicht skalieren – sonst passen die Wechselhöhen nicht mehr. Im Slicer die erste Schicht so einstellen wie im Plan (Standard 0,2 mm).", "run": "_chrOpen()"},
  {"b": "Generatoren A–Z", "i": "🖼️", "t": "Lithophane", "k": "lithophane foto bild relief licht leuchtbild durchlicht hintergrundlicht lampe geschenk kugel weihnachtskugel christbaumkugel ornament anhänger", "was": "Aus einem Foto wird ein dünnes Relief, das erst vor einer Lichtquelle das Bild zeigt: Dünne Stellen leuchten hell, dicke bleiben dunkel.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Lithophane“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Lade unter <b>📷 Bild wählen</b> ein Foto oder PNG.", "Stell <b>Breite</b>, <b>Max-Dicke</b> und <b>Basis-Dicke</b> ein.", "Erhöh die <b>Auflösung</b> für mehr Detail und füg bei Bedarf einen <b>Rahmen</b> hinzu.", "Mit <b>Negativ (hell = dick)</b> kehrst du die Wirkung um. Klick dann auf <b>✓ Erstellen</b>.", "<b>Weihnachtskugel:</b> Oben <b>🎄 Kugel</b> wählen und <b>Durchmesser</b>, <b>Öffnung unten</b> (für die LED) und <b>Öffnung oben</b> einstellen. Mit <b>Bild von/bis</b>, <b>Rundum</b> und <b>Wiederholen</b> legst du fest, wo das Foto liegt. <b>Einpassen</b>, <b>Zuschneiden</b> oder <b>Strecken</b> bestimmt, wie es in den Bereich kommt. <b>Relief innen</b> hält die Kugel außen glatt, <b>Relief außen</b> zeigt das Bild auch ausgeschaltet als Struktur, die <b>Aufhänge-Öse</b> wird fest angedruckt."], "tipp": "Das flache Lithophane druckst du am besten stehend. Die Kugel stellst du auf die untere Öffnung und druckst die untere Hälfte mit Baum-Stützen, mit weißem Filament und 100 % Füllung.", "run": "_openLithoModal()", "video": "lithophane"},
  {"b": "Generatoren A–Z", "i": "⛏️", "t": "Minecraft-Figur", "k": "minecraft figur steve alex zombie skelett enderman beweglich gelenke stifte mehrfarbig spielfigur", "was": "Eine Figur wie Steve, Alex, Zombie, Skelett oder Enderman in den Proportionen aus dem Spiel. Arme, Beine und Kopf bewegen sich auf kleinen Stiften.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Minecraft-Figur“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Eine <b>Figur</b> wählen und die <b>Höhe</b> einstellen", "Für die Gelenke <b>Stramm</b>, <b>Mittel</b> oder <b>Locker</b> wählen", "<b>Mehrfarbig</b> (eigene Farbteile für AMS) oder <b>Einfarbig</b> (Augen und Mund vertieft, zum Ausmalen) wählen", "Unter Ausgabe <b>Druckplatte</b> oder zum Ansehen <b>Als Figur</b> wählen, dann <b>✓ Erstellen</b>"], "tipp": "Die Teile liegen schon druckfertig auf der Platte und brauchen keine Stützen. Die Stifte werden einzeln gedruckt und eingesteckt.", "run": "_mcfOpen()"},
  {"b": "Generatoren A–Z", "i": "⬡", "t": "Muster-Generator", "k": "muster pattern waben asanoha voronoi wellen raute gitter svg laser plotter lesezeichen untersetzer", "was": "Du füllst einen Umriss mit einem Gittermuster, zum Beispiel Waben, Asanoha oder Voronoi. Das Ergebnis speicherst du als SVG für Laser oder Plotter oder legst es als flaches Teil in die Szene.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Muster-Generator“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Wähle als Umriss <b>Rechteck</b>, <b>Ellipse</b> oder <b>SVG laden…</b> und stell <b>Breite</b>, <b>Höhe</b>, <b>Ecken</b>, <b>Rand</b> und <b>Aufhänger</b> ein.", "Wähle ein Muster: <b>Wabe</b>, <b>Asanoha</b>, <b>Dreieck</b>, <b>Quadrat</b>, <b>Raute</b>, <b>Wellen</b> oder <b>Voronoi</b>.", "Stell <b>Zellgröße</b>, <b>Stegbreite</b> und <b>Drehung</b> ein. Mit <b>Kehlen</b> runden sich die Ecken an den Stegkreuzungen.", "Für den Laser stellst du die <b>Schnittfuge</b> ein, für 3D die <b>Dicke 3D</b>. Dann klickst du auf <b>💾 SVG speichern</b> oder <b>✓ In die Szene</b>."], "tipp": "Die Schnittfuge ist nur für den Laser gedacht. Beim 3D-Druck lässt du sie auf 0.", "run": "_pgOpen()"},
  {"b": "Generatoren A–Z", "i": "🏷️", "t": "Namensschild", "k": "name namensschild schild schlüsselanhänger keychain text schreibschrift platte öse zweifarbig mehrfarbig", "was": "Du bekommst ein Namensschild mit erhabenem Text auf einer Platte. Es geht auch freistehend in Schreibschrift, auf Wunsch mit Öse als Schlüsselanhänger.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Namensschild“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Gib den <b>Name / Text</b> ein und wähle bei <b>Bauart</b> entweder <b>Freistehend (Schreibschrift)</b> oder <b>Text auf Platte</b>.", "Such dir eine <b>Schrift</b> aus. Weitere findest du über <b>🔎 Katalog</b>, eigene Schriften lädst du mit <b>＋ Eigene Datei</b>.", "Stell <b>Texthöhe</b>, <b>Erhebung</b> und <b>Platte</b> ein. Bei Text auf Platte kommen noch <b>Rand</b>, <b>Eckenradius</b> und die <b>Farben</b> für Platte und Text dazu.", "Setz bei Bedarf den Haken bei <b>Öse für Schlüsselanhänger</b> und wähle <b>Loch-Ø</b> und <b>Position</b>.", "Klick auf <b>✓ Erstellen</b>."], "tipp": "Druck das Schild am besten zweifarbig. Im 3MF-Export werden Platte und Text zu zwei Filamenten.", "run": "_openNameModal()", "video": "namensschild"},
  {"b": "Generatoren A–Z", "i": "🪴", "t": "Organic Planter", "k": "übertopf blumentopf planter pflanze keramik organisch handgemacht wülste untersetzer abfluss topf ton", "was": "Du erzeugst einen Übertopf, der wie von Hand aus Ton aufgebaut aussieht: gestapelte Wülste, leicht unrund und mit Steinstruktur. Auf Wunsch kommt ein passender Untersetzer dazu.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Organic Planter“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Maße</b> <b>Höhe</b>, <b>Ø oben</b>, <b>Boden-Ø</b> und <b>Bauch</b> einstellen.", "Unter <b>Organische Form</b> <b>Wülste</b>, <b>Wulst-Tiefe</b>, <b>Naht-Welle</b>, <b>Unrundheit</b> und <b>Struktur</b> anpassen, mit <b>🎲 Neue Variante würfeln</b> variieren.", "Unter <b>Druck &amp; Technik</b> <b>Wandstärke</b>, <b>Bodenstärke</b> und <b>Abfluss</b> wählen (0 Schlitze = dichter Boden).", "Optional <b>Passenden Untersetzer mitbauen</b> anhaken, dann <b>✓ Erstellen</b>."], "tipp": "Aufrecht und ohne Stützen drucken. Übertopf und Untersetzer druckst du einzeln.", "run": "_openOplModal()"},
  {"b": "Generatoren A–Z", "i": "🍄", "t": "Pilz", "k": "pilz herbst deko hut stiel gewinde schrauben fliegenpilz led teelicht lichtpunkte zweiteilig", "was": "Du baust einen Deko-Pilz aus zwei Teilen, Stiel und Hut, die du mit einem echten Gewinde zusammenschraubst. Auf Wunsch bekommt er eine Tasche für ein LED-Teelicht.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Pilz“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Stell beim <b>Hut</b> <b>Ø</b>, <b>Höhe</b> und <b>Form</b> ein und wähl die Haut: <b>Glatt</b>, <b>Gefurcht</b>, <b>Rau</b>, <b>Tupfen</b> oder <b>Schuppen</b>.", "Forme den <b>Stiel</b> mit <b>Ø unten</b>, <b>Höhe</b>, <b>Verjüngung</b>, <b>Bauch</b>, <b>Rippen</b> und <b>Drall</b>.", "Mit <b>💡 LED-Einsatz</b> bekommt der Stiel unten eine Tasche, optional mit <b>Lichtpunkten</b> und <b>Schriftzug</b>.", "Stell unter <b>Verbindung &amp; Druck</b> <b>Steigung</b>, <b>Spiel</b> und <b>Stiel hohl</b> oder <b>Stiel massiv</b> ein.", "Klick auf <b>✓ Erstellen</b>."], "tipp": "Beide Teile stehen richtig herum auf der Platte und brauchen keine Stützen. Klemmt der Hut beim Schrauben, erhöh das Spiel.", "run": "_pilzOpen()"},
  {"b": "Generatoren A–Z", "i": "🍄", "t": "Pilzlampe", "k": "pilzlampe pilz lampe herbst ähren gräser relief schirm led puck gewinde schrauben deko leuchte", "was": "Du baust eine Herbstlampe aus zwei Teilen: einen dünnen, bauchigen Schirm mit Ähren- oder Gräser-Relief und einen gerippten Fuß. Im Fuß liegt ein LED-Puck in einem Napf, den Schirm schraubst du auf.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Pilzlampe“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Schirm</b> <b>Ø</b>, <b>Höhe</b>, <b>Öffnung oben</b>, <b>Bauch-Lage</b>, <b>Überhang max</b> und <b>Wand</b> einstellen.", "Beim <b>Relief</b> <b>🌾 Ähren</b>, <b>🌿 Gräser</b> oder <b>Glatt</b> wählen und <b>Dichte</b>, <b>Wuchshöhe</b> und <b>Relief-Höhe</b> anpassen (<b>🎲 Neue Halme würfeln</b>).", "Unter <b>Fuß</b> <b>Ø unten</b>, <b>Höhe</b>, <b>Bauch</b>, <b>Rippen</b> und <b>Wand</b> festlegen.", "Bei <b>Licht &amp; Gewinde</b> <b>Puck-Ø</b>, <b>Steigung</b>, <b>Gewindehöhe</b> und <b>Spiel</b> einstellen, dann <b>✓ Erstellen</b>."], "tipp": "Beide Teile werden aufrecht und ohne Stützen gedruckt. Eine Wand von 1,2–1,6 mm aus weißem PLA lässt das Licht schön durchscheinen.", "run": "_plpOpen()"},
  {"b": "Generatoren A–Z", "i": "🌳", "t": "Pflanzen", "k": "pflanzen baum laubbaum apfelbaum tanne busch kaktus palme spielstadt modellbau kinder", "was": "Bäume und Pflanzen für die Spielwelt: Laubbaum, Apfelbaum mit roten Äpfeln, Tanne, Busch, Kaktus mit Blüte und Palme mit Kokosnüssen. Kronen und Äste sind so geformt, dass sie ohne Stützen drucken.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Pflanzen“, Thema „Spielwelt & Kinder“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Vorlage</b> eine Pflanze wählen.", "<b>Höhe</b> einstellen und beim <b>Sockel</b> <b>Runder Fuß</b> oder <b>Ohne</b> wählen.", "Mit <b>Variante</b> eine andere Zufallsform ausprobieren.", "Farben wählen und <b>✓ Erstellen</b> klicken."], "tipp": "Mehrere Bäume mit verschiedenen Varianten bauen, dann wirkt der Wald natürlicher. Ohne Fuß lassen sie sich in eine Landschaftsplatte kleben.", "run": "_kgOpen('pflanze')"},
  {"b": "Generatoren A–Z", "i": "🧩", "t": "Puzzle", "k": "puzzle foto steckpuzzle teile bild mehrfarbig tablett herz oval 3mf kinder", "was": "Aus einem Foto wird ein echtes Steckpuzzle mit Nasen, die richtig ineinander halten. Ohne Bild bekommst du einfarbige Teile zum Bemalen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Puzzle“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Optional mit <b>🖼️ Bild wählen …</b> ein Foto laden, dann <b>Farben</b> und <b>Kachel</b> einstellen", "Als Form <b>Rechteck</b>, <b>Oval</b> oder <b>Herz</b> wählen, dazu <b>Breite</b>, <b>Höhe</b> und <b>Dicke</b>", "Die Teilung über <b>Spalten</b> und <b>Zeilen</b> festlegen, außerdem <b>Nasen</b> und <b>Unregelmäßig</b> (<b>🎲 Schnitt neu würfeln</b>)", "<b>Spiel</b> einstellen, <b>Zusammengesteckt</b> oder <b>Druckplatte</b> wählen, bei Bedarf <b>Mit Tablett</b>", "Auf <b>✓ Erstellen</b> klicken"], "tipp": "Spiel 0,2–0,3 mm passt auf den meisten Druckern. Bei einer Dicke unter 3 mm verziehen sich die Teile gern.", "run": "_pzlOpen()"},
  {"b": "Generatoren A–Z", "i": "📇", "t": "QR-Code", "k": "qr qrcode code link url wlan schild platte schlüsselanhänger öse scannen", "was": "Du bekommst eine scannbare QR-Code-Platte zum Drucken. Die Module stehen erhaben auf der Platte. Hinein passen ein Link, ein Text oder WLAN-Daten.", "wo": "Oben Reiter <b>GENERATOREN</b> → „QR-Code“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Gib unter <b>Inhalt (Link, Text, WLAN …)</b> ein, was der Code enthalten soll.", "Stell <b>Größe</b>, <b>Modul-Höhe</b> und die Dicke der <b>Platte</b> ein.", "Runde die Ecken bei Bedarf mit dem <b>Eckenradius</b> ab.", "Wenn du einen Schlüsselanhänger willst, setz den Haken bei <b>Öse für Schlüsselanhänger</b> und wähle <b>Loch-Ø</b> und <b>Position</b>.", "Klick auf <b>✓ Erstellen</b>."], "tipp": "Druck den Code am besten zweifarbig: helle Platte, dunkle Module.", "run": "_openQRModal()"},
  {"b": "Generatoren A–Z", "i": "🧪", "t": "Rasterbox", "k": "rasterbox gridfinity bin box grundplatte einlage raster sortierbox schublade magnete stapelbar organizer", "was": "Du erzeugst Teile für das Gridfinity-Raster mit 42 mm pro Einheit: Boxen (Bins), Grundplatten oder Einlagen mit Tasche, um Schubladen zu ordnen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Rasterbox“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Oben den Reiter <b>📦 Bin</b>, <b>⬛ Platte</b> oder <b>🧪 Einlage</b> wählen.", "Bei <b>Raster</b> <b>Breite X</b>, <b>Tiefe Y</b> und, beim Bin, <b>Höhe</b> in Einheiten (U) einstellen.", "Beim Bin <b>Wandstärke</b>, <b>X-Teiler</b>/<b>Y-Teiler</b>, <b>Stapelrand</b> und <b>Magnete</b> festlegen, bei der Platte die <b>Magnet-/Schrauben-Löcher</b>.", "Bei der Einlage die Taschenform (<b>Rechteck</b>, <b>Kreis</b>, <b>Sechseck</b>), <b>Taschentiefe</b> und <b>Boden</b> wählen, dann <b>✓ Erstellen</b>."], "tipp": "Die Magnet-Option bohrt Löcher für Ø6,5-mm-Magnete.", "run": "_openGFModal()"},
  {"b": "Generatoren A–Z", "i": "🛡️", "t": "Rohr-Klipp", "k": "rohr klipp schutzschale rohrschutz clip überschnappen gebogen biegung kabelbinder ht-rohr schale", "was": "Erzeugt eine Schutzschale, die du seitlich über ein gerades oder gebogenes Rohr schnappst – sie folgt einem echten Kreisbogen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Rohr-Klipp“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["<b>Rohr-Ø</b>, <b>Spiel</b>, <b>Wandstärke</b> und <b>Länge</b> einstellen.", "Unter <b>Biegung</b> <b>Durchhang</b>, <b>Radius</b> oder <b>Gerade</b> wählen und den Wert eingeben.", "<b>Umschlingung</b> (über 180° schnappt er ein), Lage der Öffnung und <b>Rastnase</b> festlegen.", "Optional <b>Enden anfasen</b> und <b>Nuten für Kabelbinder</b>, dann <b>✓ Erstellen</b>."], "tipp": "Mit Öffnung zur Seite liegt der Klipp flach auf dem Bett und druckt ohne Stützen (PETG oder PLA, 2–3 Wände).", "run": "_rkOpen()"},
  {"b": "Generatoren A–Z", "i": "🚪", "t": "Scharnier", "k": "scharnier gelenk print-in-place stift blatt drehgelenk tür klappe spiel schraublöcher", "was": "Erzeugt ein bewegliches Scharnier aus zwei Blättern mit Stift, das am Stück gedruckt wird (Print-in-Place) – z. B. für Klappen und Türchen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Scharnier“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["<b>Länge</b>, <b>Blattbreite</b> und <b>Blattdicke</b> einstellen.", "Beim Gelenk <b>Stift-Ø</b> und <b>Spiel</b> wählen.", "<b>Schraublöcher</b>: <b>Ja (Ø 3,4)</b> oder <b>Ohne</b>.", "<b>✓ Scharnier erzeugen</b> klicken."], "tipp": "Flach drucken, das Gelenk NICHT stützen und nach dem Druck vorsichtig losbrechen/bewegen.", "run": "_openPipModal()"},
  {"b": "Generatoren A–Z", "i": "📦", "t": "Scharnier-Box", "k": "scharnier box klappbox print-in-place schachtel dose deckel verschluss lippe aufbewahrung", "was": "Erzeugt eine Klappbox aus zwei Halbschalen mit eingebautem Scharnier, die am Stück gedruckt wird (Print-in-Place).", "wo": "Oben Reiter <b>GENERATOREN</b> → „Scharnier-Box“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["<b>Breite</b>, <b>Tiefe</b>, <b>Höhe (zu)</b> und <b>Wandstärke</b> einstellen.", "Beim Scharnier <b>Stift-Ø</b> und <b>Spiel</b> wählen.", "<b>Verschluss</b>: <b>Mit Lippe</b> oder <b>Ohne</b>.", "<b>✓ Erstellen</b> klicken."], "tipp": "Flach/offen OHNE Stützen drucken und danach einmal auf- und zuklappen, um das Scharnier zu lösen.", "run": "_openHingeModal()"},
  {"b": "Generatoren A–Z", "i": "🛤️", "t": "Schienen", "k": "schienen gleis holzeisenbahn brio eisenbahn kurve weiche kreuzung prellbock zug kinder", "was": "Schienen für die Holzeisenbahn im Brio-Maß: Gerade, Kurve, kleine Kurve, Weiche, Kreuzung und Prellbock. Die Stücke passen zusammen und mit gekauften Holzschienen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Schienen“, Thema „Spielwelt & Kinder“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Vorlage</b> das Stück wählen, z. B. <b>➖ Gerade</b> oder <b>↪️ Kurve</b>.", "<b>Länge</b> (in 18-mm-Schritten wie bei Brio), <b>Radius</b> und <b>Winkel</b> einstellen, bei der Weiche die Richtung.", "Bei <b>Enden</b> wählen, wo ein Zapfen und wo ein Loch sitzt.", "Passt es nicht zu deinen Holzschienen? Unter <b>Maße</b> <b>Zapfen-Ø</b>, <b>Hals-Breite</b> und <b>Spiel im Loch</b> anpassen. Dann <b>✓ Erstellen</b>."], "tipp": "Liegt flach und druckt ohne Stützen. Die Maße stammen aus dem Internet und sind noch nicht an einer echten Schiene geprüft. Erst ein kurzes Stück testen.", "run": "_kgOpen('schienen')"},
  {"b": "Generatoren A–Z", "i": "🚢", "t": "Schiff", "k": "schiff titanic segelschiff galeone dreimaster raddampfer schlachtschiff zerstörer modell wasserlinie mehrfarbig", "was": "Ein Schiffsmodell, vom Segler über die Titanic bis zum Kriegsschiff. Masten, Schornsteine, Türme und vieles mehr lassen sich frei kombinieren.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Schiff“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Schiffstyp (Vorlage)</b> zum Beispiel <b>🚢 Titanic</b> oder <b>🏴‍☠️ Galeone</b> wählen", "<b>Länge</b> und <b>Breite</b> einstellen, dann <b>Wasserlinie</b> oder <b>Vollrumpf + Ständer</b> wählen", "<b>Masten und Segel</b>, <b>Dampfer und Aufbauten</b>, <b>Bewaffnung</b> und <b>Details</b> anpassen", "<b>Mehrfarbig</b> oder <b>Einfarbig</b> wählen, dann <b>✓ Erstellen</b>"], "tipp": "Mit Wasserlinie geht der Druck ohne Stützen. Der Vollrumpf und Segel bzw. Rahen brauchen Stützen, am besten Baumstützen.", "run": "_shfOpen()"},
  {"b": "Generatoren A–Z", "i": "🫙", "t": "Schraubdose", "k": "schraubdose dose deckel gewinde behälter schraubdeckel dosen riffelung aufbewahrung vorratsdose", "was": "Erzeugt eine runde Dose mit passendem Schraubdeckel in einem Schritt – zum Aufbewahren von Kleinteilen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Schraubdose“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["<b>Durchmesser</b>, <b>Höhe</b> und <b>Wandstärke</b> einstellen.", "Beim Gewinde <b>Steigung</b>, <b>Gewindehöhe</b> und <b>Spiel</b> wählen.", "Für den Deckel <b>Riffelung</b> oder <b>Glatt</b> wählen.", "<b>✓ Dose + Deckel erzeugen</b> klicken."], "tipp": "Der Deckel liegt schon in Drucklage; zum Zudrehen umdrehen und bei klemmendem Deckel das <b>Spiel</b> erhöhen.", "run": "_openJarModal()"},
  {"b": "Generatoren A–Z", "i": "🔩", "t": "Schraube / Mutter", "k": "schraube mutter gewinde metrisch m3 m6 sechskant torx senkkopf scheibe linksgewinde din", "was": "Erzeugt druckbare Schrauben, Muttern und Unterlegscheiben mit metrischem Gewinde nach Norm (M2 bis M12), z. B. als Ersatzteil oder für eigene Konstruktionen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Schraube / Mutter“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Typ</b> wählen: <b>Außen</b>, <b>Innen</b>, <b>Senk</b>, <b>Torx</b>, <b>Schloss</b>, <b>Mutter</b> oder <b>Scheibe</b>.", "<b>Größe (metrisch)</b> von <b>M2</b> bis <b>M12</b> anklicken.", "Bei Schrauben <b>Länge</b>, <b>Gewinde</b> (ganz links = Vollgewinde) und <b>Kopfhöhe</b> einstellen; bei Muttern das <b>Spiel</b>, bei Scheiben den <b>Außen-Ø</b>.", "Bei Bedarf <b>Linksgewinde</b> anhaken, dann <b>✓ Erstellen</b>."], "tipp": "Für Muttern ist das <b>Spiel</b> zum Schraubengewinde einstellbar (Standard 0,4 mm) – erhöhen, wenn die Mutter klemmt.", "run": "_openScrewModal()"},
  {"b": "Generatoren A–Z", "i": "🕳️", "t": "Schraubenloch", "k": "schraubenloch bohrung loch durchgangsloch kernloch innengewinde senkung abziehen metrisch din", "was": "Erzeugt einen fertigen Bohrungs-Körper nach Norm, den du in dein Bauteil schiebst und abziehst – für Schrauben von M2 bis M12, wahlweise mit Senkung für den Kopf.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Schraubenloch“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["<b>Größe (metrisch)</b> wählen, z. B. <b>M3</b> oder <b>M6</b>.", "Unter <b>Art des Lochs</b>: <b>Durchgang</b>, <b>Kernloch</b> (zum Gewindeschneiden) oder <b>Gewinde</b> (gedrucktes Innengewinde).", "<b>Senkung für den Kopf</b>: <b>keine</b>, <b>Senkung</b> (90°) oder <b>Zylinder</b>; dazu die <b>Tiefe</b> einstellen.", "<b>✓ Erstellen</b> – das Loch kommt als Bohrung markiert; ins Bauteil schieben, beides wählen, <b>⊖ Abziehen</b>."], "tipp": "Beim Durchgangsloch die <b>Tiefe</b> ruhig größer als das Bauteil wählen; beim Gewindeloch regelt <b>Spiel</b> die Passung.", "run": "{_openScrewModal();_screwSetType('loch');}"},
  {"b": "Generatoren A–Z", "i": "🫗", "t": "Silikon-Gießform", "k": "silikon gießform gussform mold negativform casting tray eiswürfel schokolade seife wachs", "was": "Um dein ausgewähltes Modell wird ein Gießrahmen für Silikon gebaut. Alternativ entsteht ein Raster-Tray für Eiswürfel oder Schokolade oder eine zweiteilige Form zum direkten Gießen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Silikon-Gießform“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Wähl zuerst das Modell in der Szene aus und öffne dann den Generator.", "Wähle den Modus <b>Gießrahmen</b>, <b>Raster-Tray</b> oder <b>2-teilig</b> und stell den <b>Schrumpf-Ausgleich</b> ein.", "Wähle die Rahmenform (<b>Adaptiv</b>, <b>Rechteckig</b> oder <b>Rund</b>) und stell <b>Stärke seitlich</b>, <b>Stärke oben</b>, <b>Wandstärke</b> und <b>Bodenplatte</b> ein.", "Bei der zweiteiligen Form legst du die <b>Trennebene</b> fest, auf Wunsch mit <b>⚖ Auto</b>, dazu <b>Passstift Ø</b> und <b>Gießkanal Ø</b>. Klick dann auf <b>✓ Erzeugen</b>."], "tipp": "Die Standfläche des Modells wird zur Einfüllöffnung. Die zweiteilige Form spannst du mit Gummibändern zusammen und gießt direkt hinein.", "run": "_openMoldModal()"},
  {"b": "Generatoren A–Z", "i": "🪝", "t": "Skadis-Haken", "k": "skadis ikea lochwand haken zapfen j-haken wand halter werkstatt organisation", "was": "Erzeugt Haken für die IKEA-Skadis-Lochwand (Ø-5-Löcher) – als J-Haken oder gerader Zapfen zum Aufhängen von Werkzeug und Zubehör.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Skadis-Haken“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Variante</b> <b>J-Haken</b> oder <b>Gerader Zapfen</b> wählen.", "<b>Tiefe</b>, <b>Stab-Ø</b> und beim J-Haken <b>Bogen hoch</b> einstellen.", "Bei <b>Befestigung</b> <b>Breite</b> und <b>Lochabstand</b> (Standard 40 mm) festlegen.", "<b>✓ Erstellen</b> klicken."], "tipp": "Zum Drucken auf die Seite legen (Auto-Ausrichten), dann geht es ohne Stützen.", "run": "_openSkadisModal()"},
  {"b": "Generatoren A–Z", "i": "🗼", "t": "Ständer", "k": "ständer halter display sockel flugzeug rakete figur zapfen teller gabel kinder", "was": "Ein Ständer, der Modelle in die Luft hält, z. B. Flugzeuge, Raketen oder Figuren. Oben sitzt ein Zapfen (für ein Loch im Modell), ein Teller (zum Ankleben oder für einen Magneten) oder eine Gabel zum Einlegen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Ständer“, Thema „Spielwelt & Kinder“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["<b>Höhe</b>, <b>Neigung</b> und <b>Stab-Ø</b> einstellen.", "Beim <b>Fuß</b> <b>Rund</b> oder <b>Eckig</b> wählen und die <b>Fuß-Größe</b> festlegen (größer = kippt nicht so leicht).", "Unter <b>Aufnahme</b> <b>Zapfen</b>, <b>Teller</b> oder <b>Gabel</b> wählen und die Größe einstellen.", "Farbe wählen und <b>✓ Erstellen</b> klicken."], "tipp": "Bis 30° Neigung druckt der Ständer ohne Stützen. Das Loch im Modell sollte 0,3 mm größer sein als der Zapfen.", "run": "_kgOpen('staender')"},
  {"b": "Generatoren A–Z", "i": "🧩", "t": "Steckbausatz", "k": "steckbausatz zapfen buchse zusammenstecken verbinder teile ohne kleber spiel bausatz", "was": "Mehrere Körper, die sich berühren, bekommen an den Kontaktstellen einen Zapfen und eine passende Buchse. So druckst du jedes Teil einzeln und steckst sie ohne Kleber zusammen.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Steckbausatz“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Alle zusammengehörigen Teile auswählen", "Für den Zapfen <b>Durchmesser</b>, <b>Einstecktiefe</b> und <b>Spiel</b> einstellen", "<b>1 Zapfen</b>, <b>2 Zapfen</b> (verdrehsicher, normal) oder <b>3 Zapfen</b> wählen", "Unter Prüfungen z. B. <b>Durchdringungen auflösen</b> und <b>Zapfen bei Bedarf verstärken</b> anhaken, dann <b>✓ Erzeugen</b>"], "tipp": "Spiel 0,2 mm ist der übliche Wert für PLA mit 0,4-mm-Düse: Die Teile halten fest und lassen sich trotzdem von Hand zusammenstecken.", "run": "_snpOpen()"},
  {"b": "Generatoren A–Z", "i": "🛣️", "t": "Straße", "k": "straße strasse straßenplatte kreuzung kurve kreisverkehr zebrastreifen sackgasse spielteppich stadt puzzle kinder", "was": "Straßenplatten für eine Spielstadt: Gerade, Kurve, Kreuzung, T-Kreuzung, Zebrastreifen, Kreisverkehr und Sackgasse, mit Gehweg, Wiese und Markierung. Die Platten werden per Puzzle zusammengesteckt und passen in jeder Drehung aneinander.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Straße“, Thema „Spielwelt & Kinder“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Vorlage</b> die Platte wählen.", "<b>Plattengröße</b> (für alle Platten gleich, Standard 144 mm), <b>Fahrbahn</b> und <b>Gehweg</b> einstellen.", "<b>Mehrfarbig</b> (Fahrbahn, Markierung, Gehweg, Wiese) oder <b>Einfarbig</b> wählen.", "<b>✓ Erstellen</b> klicken und weitere Platten genauso bauen."], "tipp": "Flach, ohne Stützen. Bei Einfarbig sind die Markierungen eingraviert. Die Autos aus dem Fahrzeug-Generator passen in eine Spur.", "run": "_kgOpen('strasse')"},
  {"b": "Generatoren A–Z", "i": "⚔️", "t": "Tabletop-Figur", "k": "tabletop miniatur 32mm figur grimdark trench soldat ritter pilger base wargaming", "was": "Eine 32-mm-Miniatur im düsteren Schützengraben-Stil für Tabletop-Spiele, mit Kopf, Rüstung, Waffe und Base. Alles ist ein eigenes Design, keine Kopie fremder Figuren.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Tabletop-Figur“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Eine <b>Vorlage</b> wählen, z. B. <b>Soldat</b>, <b>Pilger</b>, <b>Ritter</b>, <b>Stoßtrupp</b> oder <b>Ketzer</b>", "Eine <b>Pose</b> wählen: <b>Stehend</b>, <b>Schreitend</b>, <b>Sturm</b> oder <b>Zielend</b>", "Unter Ausstattung <b>Kopf</b>, <b>Körper</b>, <b>Waffe</b>, <b>Linke Hand</b> und Extras anpassen", "<b>Höhe</b> und <b>Base</b> einstellen, dann <b>✓ Erstellen</b> oder <b>🎲 Neue Variante würfeln</b>"], "tipp": "Für die 32-mm-Details am besten in Resin drucken oder mit FDM und feiner Düse.", "run": "_tfgOpen()"},
  {"b": "Generatoren A–Z", "i": "🎂", "t": "Tortentopper", "k": "tortentopper torte topper schriftzug name hochzeit geburtstag steckpin schreibschrift herz datum", "was": "Du machst einen Schriftzug mit Steckpins für die Torte. i-Punkte, getrennte Buchstaben und Symbole werden automatisch über Stege verbunden.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Tortentopper“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Gib den <b>Text</b> ein. Mit <b>Symbole</b> fügst du ♥ ★ ✿ ein, auf Wunsch auch das <b>Datums-Herz</b>.", "Wähle die <b>Schrift</b> (auch über <b>🔎 Katalog</b>), optional eine <b>Zweite Schrift</b> mit <b>Trennlinie</b>.", "Stell <b>Texthöhe</b>, <b>Dicke</b>, <b>Kanten runden</b>, <b>Überlappung</b> und <b>Steg-Breite</b> ein.", "Wähle unter <b>Steckpins</b> die Anzahl (1, 2 oder ohne), dazu <b>Pin-Länge</b> und <b>Pin-Breite</b>.", "Klick auf <b>✓ Erstellen</b>."], "tipp": "Lass die Unterkante ungerundet, damit der Topper gut auf der Druckplatte haftet. Wenn du sie doch rundest, hilft ein Brim.", "run": "_ttOpen()"},
  {"b": "Generatoren A–Z", "i": "🛥️", "t": "U-Boot", "k": "u-boot uboot unterseeboot atom-u-boot comic gelb periskop turm wasser ständer kinder", "was": "Ein U-Boot zum Spielen oder Ausstellen: Atom-U-Boot, klassisches U-Boot mit Deck und Kanone oder dickes Comic-U-Boot mit Bullaugen. Aufgetaucht liegt es flach auf einer Wasserplatte mit Wellen. Ganz gibt es den vollen Rumpf mit Schraube und einen Gabel-Ständer.", "wo": "Oben Reiter <b>GENERATOREN</b> → „U-Boot“, Thema „Spielwelt & Kinder“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Vorlage</b> <b>🛥️ Atom-U-Boot</b>, <b>⚓ Klassisch</b> oder <b>🟡 Comic-U-Boot</b> wählen.", "<b>Länge</b>, <b>Dicke</b> und <b>Turm-Höhe</b> einstellen, dazu <b>Periskope</b>, <b>Bullaugen</b> und <b>Deckkanone</b>.", "Unter <b>Darstellung</b> <b>Aufgetaucht</b> (mit oder ohne <b>Wasserplatte</b>) oder <b>Ganz + Ständer</b> wählen.", "Farben wählen und <b>✓ Erstellen</b> klicken."], "tipp": "Beide Darstellungen drucken ohne Stützen. Beim ganzen U-Boot stehen die unteren Ruder und ein Schraubenblatt auf dem Bett.", "run": "_kgOpen('uboot')"},
  {"b": "Generatoren A–Z", "i": "🏺", "t": "Vase", "k": "vase übertopf blumenvase rotationskörper vasenmodus spiralmodus wandstärke rillen lowpoly organisch twist welle", "was": "Du gestaltest eine Vase oder einen Übertopf als Drehkörper. Profil, Querschnitt und Oberfläche sind frei einstellbar, eine Vorschau dreht sich live mit.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Vase“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Körperprofil</b> mit <b>Öffnung</b>, <b>Hals</b>, <b>Bauch</b>, <b>Hals-Pos</b> und <b>Boden</b> die Silhouette formen.", "Bei <b>Größe</b> <b>Höhe</b>, <b>Breite</b> und <b>Wandstärke</b> einstellen.", "Einen <b>Querschnitt</b> wählen (<b>Rund</b>, <b>Dreieck</b>, <b>Quadrat</b>, <b>Vieleck</b>, <b>Welle</b>) und eine <b>Oberfläche</b> (<b>Glatt</b>, <b>Rillen</b>, <b>Low Poly</b>, <b>Organisch</b>, dort <b>🎲 Neu würfeln</b>).", "Unter <b>Form</b> mit <b>Twist</b>, <b>Schwung</b> und <b>Perioden</b> verdrehen, dann <b>✓ Vase erstellen</b>."], "tipp": "Mit Wandstärke entsteht eine echte Vase mit Wand und Boden, oben offen. Wandstärke 0 ergibt eine dünne Einzelwand für den Vasen-/Spiralmodus im Slicer.", "run": "_openVaseModal()", "video": "vase"},
  {"b": "Generatoren A–Z", "i": "🧰", "t": "Werkzeug-Einleger", "k": "werkzeug einleger gridfinity foto din a4 tasche kontur schublade organizer werkstatt aufbewahrung", "was": "Aus einem Foto deines Werkzeugs auf einem DIN-A4-Blatt entsteht ein Gridfinity-Einsatz mit passender Tasche. Das Blatt dient dabei als Maßstab.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Werkzeug-Einleger“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Werkzeug auf weißes A4 legen, senkrecht von oben fotografieren und mit <b>📷 Foto wählen</b> laden (<b>A4 hoch</b>/<b>A4 quer</b>).", "Die 4 Papierecken anklicken, die Erkennung mit <b>Schwelle</b> und <b>Glättung</b> verfeinern.", "Unter <b>Tasche</b> <b>Spiel</b> und <b>Tiefe</b> einstellen und <b>Mit Fingermulde</b> oder <b>Ohne</b> wählen.", "Unter <b>Box</b> <b>Höhe</b> und <b>Gridfinity-Füße</b> oder <b>Flache Platte</b> wählen, dann <b>✓ Erzeugen</b>."], "tipp": "Mit 0,5 mm Spiel sitzt das Werkzeug saugend, mit 1 mm locker. Als Taschentiefe nimmst du meist die halbe Werkzeugdicke.", "run": "_wzOpen()", "video": "werkzeug-einleger"},
  {"b": "Generatoren A–Z", "i": "⚙️", "t": "Zahnrad", "k": "zahnrad ritzel zahnstange evolvente modul zähne getriebe bohrung stirnrad antrieb", "was": "Erzeugt echte Evolventen-Stirnräder mit Modul, Zähnezahl, Breite und Mittenbohrung – auf Wunsch mit passender Zahnstange.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Zahnrad“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["<b>Modul</b> (Zahngröße) und Anzahl <b>Zähne</b> einstellen.", "<b>Breite</b> (Dicke) und <b>Bohrung</b> (0 = keine) festlegen.", "Optional <b>Passende Zahnstange erzeugen</b> anhaken und deren <b>Länge</b> und <b>Breite</b> wählen.", "<b>✓ Erstellen</b> – die Info zeigt Teilkreis- und Außen-Ø."], "tipp": "Zahnräder und Zahnstange kämmen nur miteinander, wenn sie dasselbe <b>Modul</b> haben.", "run": "_openGearModal()"},
  {"b": "Generatoren A–Z", "i": "🚂", "t": "Zug", "k": "zug lok lokomotive dampflok e-lok wagen personenwagen güterwagen kesselwagen holzeisenbahn brio räder magnet kinder", "was": "Lok oder Wagen für die Holzeisenbahn: Dampflok, E-Lok, Personenwagen, Güterwagen oder Kesselwagen. Die Räder drehen sich und laufen in den Rillen der Schienen. Gekuppelt wird mit Magneten oder gedruckten Haken.", "wo": "Oben Reiter <b>GENERATOREN</b> → „Zug“, Thema „Spielwelt & Kinder“ (oder rechts „Generatoren ▾“). Später ändern: Teil auswählen → „✏️ Im Generator bearbeiten“.", "s": ["Unter <b>Vorlage</b> eine Lok oder einen Wagen wählen.", "<b>Länge</b> und <b>Kupplung</b> (<b>Magnet</b>, <b>Haken</b> oder <b>Keine</b>) einstellen.", "Farben wählen und <b>✓ Erstellen</b> klicken. Dazu kommen 4 Räder und 4 Steckachsen als eigene Teile.", "Nach dem Druck: Rad von unten in den Radkasten halten und die Achse von außen durchstecken, bis sie stramm sitzt."], "tipp": "Für die Magnet-Kupplung Magnete 6 × 3 mm einkleben. Vorne und hinten müssen verschiedene Pole nach außen zeigen, sonst stoßen sich die Wagen ab.", "run": "_kgOpen('zug')"}
);
